insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B6.1.1.1', 'Identify parts of a computer, technology tools and history of computers', 'B6.1.1.1.1', 'Learn about the Generation of Computers G u id e l e a r n e r s t o d is c u s s t h e G e n e r a t i o n o f C o m p u t e r s', 'Microprocessors - Super Computers, Mainframe, Minicomputers and the main computer mixed Microcomputers, Mobile Phones, etc', 10),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B6.1.1.1', 'Identify parts of a computer, technology tools and history of computers', 'B6.1.1.1.2', 'Identify components of a Computer System: Hardware, Software and Liveware', 'Guide learners to identify Hardware (input, output, storage and communication), Software, Liveware and discuss the components and how they are used NB: the discussion should be limited to definition level.', 20),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B6.1.1.1', 'Identify parts of a computer, technology tools and history of computers', 'B6.1.1.1.3', 'Identify the left, right mouse button, holding of mouse, performing single, double and triple clicking, dragging object and using the scroll wheel Guide learners to master the use of mouse through practical sessions and games', 'Support learners to liken the Recycle bin and its use to the real-world office trash can.', 30),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B6.1.1.1', 'Identify parts of a computer, technology tools and history of computers', 'B6.1.1.1.4', 'Demonstrate proper use of keyboarding technique. Guide learners to type stories using Word Processor or typing tutorial (', 'e.g. Mavis Beacon) to improve typing speed', 40),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B6.1.1.1', 'Identify parts of a computer, technology tools and history of computers', 'B6.1.1.1.5', 'Summarise the generation of computers (second generation of computers.) Group learners into groups', 'Guide them to summarise the generation of computers. After, let them present their findings in groups to the class. eg. First generation, Second generation, Third generation etc.', 50),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.1', 'Explore the use of the desktop Background, changing the themes colours and User account. (', 'e.g. classic, icons and Taskbar of the background) Guide learners to the use of the desktop Background, change the themes colours and the User account.', 60),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.2', 'Demonstrate the use of the Recycle Bin or Trash Can', 'Guide learners to use the recycle bin by deleting and viewing deleted files.', 70),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.4', 'Explore the use of Copy, Paste, Delete tools, the moving of folders by using the Desktop Pop-Up menu', 'Guide learners to the use of the Copy, Paste, Delete tools, the moving of folders by using the Desktop Pop-Up menu.', 80),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.5', 'Illustrate the use of File Explorer window and locations of the computer through the file explorer', 'Guide learners to the use File Explorer window and locations of the computer through the file explorer.', 90),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.6', 'Locate the hard drives, and other removable storage icons in the File explorer', 'Guide learners to locate the hard drives and other removable storage icons in the File explorer.', 100),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.7', 'Use the File Explorer Ribbon (Home Ribbon only), that is, the use of the Clipboard and Organise tools of the Home Ribbon of the File Explorer, as well as the Open New Window and Close tools of the File Menu of the File Explorer', 'Guide learners to use the File Explorer Ribbon (Home Ribbon only); the use of the Clipboard and Organise tools of the Home Ribbon of the File Explorer, and Open New Window and Close tools of the File Menu of the File Explorer.', 110),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.8', 'Demonstrate the use of the navigation Pane of the File Explorer to access different locations of the computer from the navigation pane', 'Guide learners to the use of the navigation Pane of the File Explorer to access different locations of the computer from the navigation pane.', 120),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.9', 'Demonstrate the use of Frequent Folders Section of the File Explorer to access frequently used locations of the computer', 'Guide learners to explore the use of Frequent Folders Section of the File Explorer to access frequently used locations of the computer.', 130),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B6.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B6.1.2.1.10', 'Demonstrate the use of Recent Files Section of the File Explorer to access frequently used files of the computer', 'Guide learners to explore the use of Recent Files Section of the File Explorer to access frequently used files of the computer.', 140),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.1', 'Identify types of data. (Integers, double, characters, float etc.) Guide learners to identify and record data in the different forms', null, 150),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.2', 'Identify more sources of data and information', 'e.g. internet (emailing, Skype, SMS etc.) Guide learners to discuss where one can get data and information.', 160),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.3', 'Demonstrate sending and receiving information from other gadgets', 'e.g. Bluetooth, Infrared, Radio, Fax, Telephones calls, SMS etc. Guide learners to mention or talk about where one can receive or send information', 170),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.4', 'Demonstrate basic manipulations on sample data', 'e.g. arranging data in a matrix table, sorting and calculations etc. Guide learners to sort data in alphabetical order (increasing and decreasing order) and perform basic calculations such as multiplying, dividing and adding vales of sample data. Learners can also be guided to generate age data from dates of birth.', 180),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.5', 'Demonstrate how to manage users of the Desktop Guide learners to brainstorm how to manage users of the Desktop', 'Use videos or pictures that show how to manage users of the Desktop. Facilitate learners to do same. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and computer science.', 190),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.6', 'Demonstrate how to collect data (', 'e.g. listening to radio, reading newspapers, interviews use of questionnaires etc.) Lead learners to collect data the community using simple questionnaire, surveys, documents, observations, and record their findings data', 200),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.7', 'Demonstrate the use of the tools for collecting data. Bring tools or pictures of the tools for collecting data', 'e.g. case studies, interviews, checklists, etc.', 210),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.8', 'Demonstrate data interpretation by computing data to gain required information (', 'e.g. Finding sum or grand total using Electronic Spreadsheet). Guide learners to make meanings out of data collected using tables, charts or Spreadsheet.', 220),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.9', 'Demonstrate data presentation in different forms', 'Guide learners to write data in tables, pictures, charts, maps, words etc. as well as type them in a Spreadsheet.', 230),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.10', 'Demonstrate how to store data', 'Guide learners to use the tools stated above to store data in different formats. eg. handwriting, phone recording, magnetic tapes, optical disc etc.', 240),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B6.1.3.1', 'Demonstrate the use of Data and identify sources of data', 'B6.1.3.1.11', 'Manipulate data to gain required output (', 'e.g. Finding sum, mean, grand totals, maximum, minimum, mode, division, multiplication etc.) Guide learners to find the mode, product, minimum value, maximum value etc. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and Computer Science.', 250),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community', 'B6.1.4.1', 'Demonstrate the use of Technology in the community', 'B6.1.4.1.1', 'Define communication. Put learners into groups, to discuss communication and present findings to the class', null, 260),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community', 'B6.1.4.1', 'Demonstrate the use of Technology in the community', 'B6.1.4.1.2', 'Identify three more technological tools for communication in the community', 'Guide learners to mention and describe the importance of technology in communication', 270),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community', 'B6.1.4.1', 'Demonstrate the use of Technology in the community', 'B6.1.4.1.3', 'Demonstrate communication with others', 'Guide learners to demonstrate communication (explain how communication is done via TV, radio, phone call, satellite etc.).', 280),
('Basic 6', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community', 'B6.1.4.1', 'Demonstrate the use of Technology in the community', 'B6.1.4.1.4', 'Identify three more importance of technology in communication', 'Guide learners to mention the importance of technology in communication NB: Technological tools stated here should be different from those stated in B5.This is to help the learner to fundamental knowledge of hardware such as robots and sensors).', 290),
('Basic 6', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint', 'B6.2.1.1', 'Demonstrate how to use Microsoft PowerPoint', 'B6.2.1.1.1', 'Demonstrate how to use the File menu, the Insert and Design Ribbon from B5', 'Guide learners to use File menu, Insert and Design Ribbons.', 300),
('Basic 6', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint', 'B6.2.1.1', 'Demonstrate how to use Microsoft PowerPoint', 'B6.2.1.1.2', 'Demonstrate how to use icons in the Text group in the Insert Ribbon', 'Guide learners to properly use the icons in the Insert Ribbon.', 310),
('Basic 6', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint', 'B6.2.1.1', 'Demonstrate how to use Microsoft PowerPoint', 'B6.2.1.1.3', 'Be able to give a 5-side presentation in MS-PowerPoint using the tools of the ribbons studied', 'Guide learners to present their work to the class NB. This is to help the learner with software knowledge such as in office applications (Presentation software).', 320),
('Basic 6', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-powerpoint', 'B6.3.1.1', 'Illustrate the use of word processing application', 'B6.3.1.1.1', 'Demonstrate how to use the File menu and Insert, Design, and Layout Ribbons from B5', 'Guide learners to use File menu, Insert, Design and Layout Ribbon.', 330),
('Basic 6', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-powerpoint', 'B6.3.1.1', 'Illustrate the use of word processing application', 'B6.3.1.1.2', 'Demonstrate how to use icons in the Text group in the Insert Ribbon', 'Guide learners to properly use the icons in the Insert Ribbon.', 340),
('Basic 6', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-powerpoint', 'B6.3.1.1', 'Illustrate the use of word processing application', 'B6.3.1.1.3', 'Be able to use the attributes of the ribbons studied in a paragraph', 'Guide the learners to create and format text in a document NB. This is to help the learner with software knowledge such as in office applications (word processing).', 350),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.1', 'Describe Databases. Guide learners through discussion in groups, to list and describe databases', null, 360),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.2', 'Identify databases and data structures', 'Guide learners to identify databases structures. ie. database structure is the collection of record type and field type definitions that comprises of the database.', 370),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.3', 'Explain Fundamental Database concepts', 'Guide learners apply the fundamental database concepts to a sample database in a class discussion', 380),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.5', 'Describe the basics of Relational Data model', 'Lead learners to describe the basics of Relational Data model. ie. rows and columns', 390),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.6', 'Identify the basics of logical Database Design', 'Guide learners to list the basics of logical database design and develop sample database design.', 400),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.7', 'Illustrate basics of relational algebra', 'Guide learners apply the basics of relational algebra in a sample database.', 410),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.8', 'Operate basics SQL: querying and manipulating data', 'Guide learners to write simple queries to retrieve specific names of students from a database of the names of all students in class database design. eg. CREATE DATABASE , SELECT and UPDATE', 420),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming. Languages (e.g. MS- Excel, Scratch, Vb Dot Net Etc.)', 'B6.5.1.1', 'Demonstrate how to manipulate data in Databases', 'B6.5.1.1.9', 'Operate basics SQL: querying and manipulating data', 'Guide learners to write simple queries to retrieve specific names of students from a database of the names of all students in class. e.g CREATE TABLE, DELETE and INSERT INTO, NB: This is to give a foundation to the learner in computing and Computer Science which is more concerned with uses of and development of programming together with fundamental principles of problem-solving and creativity.', 430),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.1', 'Demonstrate how to use the ribbons under the home ribbons', '(i.e. clip board, styles, fonts, paragraph and editing) Guide learners to do a presentation on the use of the ribbons under the home button.', 440),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.2', 'Learners to create basic worksheets using Microsoft Excel 2016', 'Guide learners to develop worksheet consisting of list of names ie. teachers, students, friends, families, etc.', 450),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.3', 'Perform calculations in an MS-Excel worksheet', 'Guide learners to develop worksheet that will help in calculating multiplication, addition and subtraction', 460),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.4', 'Modify an MS-Excel worksheet', 'Guide learners to modify worksheet by adding the age of learners in the class to the list of learners created in an earlier class.', 470),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.5', 'Modify the appearance of data within a worksheet', 'Show examples of modified data in (a) worksheet(s), either on projected screens or pictures. Guide learners to modify the appearance of data within a worksheet.', 480),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.6', 'Manage Excel workbooks. Guide learners to properly name MS-Excel workbooks and store them in folders for retrieval later', null, 490),
('Basic 6', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Electronic Spreadsheet (tabs and Ribbons Manipulation)', 'B6.5.3.1', 'Demonstrate how to use Spreadsheet', 'B6.5.3.1.7', 'Print the content of an MS-Excel worksheet', 'Guide learners to adjust margins to suit the A4 paper size for printing in landscape and portrait. NB. This is to help the learner with software knowledge such as in office applications (Electronic spreadsheet application).', 500),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B6.6.1.1', 'Demonstrate how to Network computers', 'B6.6.1.1.1', 'Give examples of facilities the internet offers', 'Guide learners to give examples of internet facilities ie. e-mail, FTP’s, www, etc. for presentation', 510),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B6.6.1.1', 'Demonstrate how to Network computers', 'B6.6.1.1.2', 'Describe the types of information available on the Internet', 'Guide learners to identify and describe the types of Information available on the Internet. eg. Educational, Financial, entertainment, etc. Group learners into groups to do this task.', 520),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B6.6.1.1', 'Demonstrate how to Network computers', 'B6.6.1.1.3', 'Identify data duplication', 'Display list of names of learners on the board and ask them to identify the duplicated data.', 530),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B6.6.1.1', 'Demonstrate how to Network computers', 'B6.6.1.1.4', 'Outline what one needs to connect to the Internet', 'Encourage learners to bring any device or pictures of devices that are needed. eg. desktop computers, Laptop computers, Mobile phones, etc. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and computer science.', 540),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.1', 'Identify the address or links window', 'Guide learners to identify the address or links window on phones other electronic gadgets with browsers,', 550),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.2', 'Recognise the status bar and list its use', 'Bring a picture of a window that has the status bar and ask the learners to point out the status and mention its functions', 560),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.3', 'Illustrate using help button', 'Guide learners to do an activity you have not tackle in class and ask them to use the help button to navigate and find the steps involved. Guide learners to carry out the stated steps.', 570),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.4', 'Recognise internet explorer speed keys', 'Ask learners to use the speed keys to open a new browser, make font size bigger in a browser, etc. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and computer science.', 580),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.5', 'Recognise Uniform Resource Locators (URLs)', 'Guide learners to discuss the properties of URLs, their uses and where they are located. Learners can practise how to enter URLs in a browser.', 590),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.6', 'Demonstrate how to return to a URL', 'Guide the learners to navigate using the back button to go to a previous page', 600),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B6.6.2.1', 'Demonstrate the use of a Web Browser', 'B6.6.2.1.7', 'Show how to find items on a page', 'Guide learners to search for items using the search textbox NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and Computer Science.', 610),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B6.6.3.1', 'Demonstrate Surfing The World Wide Web', 'B6.6.3.1.1', 'Recognize resource locators (URLs)', 'Guide learners to identify what URLs is. Group learners into groups of five or less, to explore on how to recognise URLs so as to aid learners to locate a resource on the web.', 620),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B6.6.3.1', 'Demonstrate Surfing The World Wide Web', 'B6.6.3.1.2', 'Illustrate how to jump directory to URLs', 'Give learners a project on how to jump directory to URLs.', 630),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B6.6.3.1', 'Demonstrate Surfing The World Wide Web', 'B6.6.3.1.3', 'Demonstrate how to return to a URL', 'Guide learners to investigate how to return to a URL.', 640),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B6.6.3.1', 'Demonstrate Surfing The World Wide Web', 'B6.6.3.1.4', 'Show how to find items on a page', 'Guide learners to discuss on how to find items on a page. Guide learners present their ideas or findings to class.', 650),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B6.6.3.1', 'Demonstrate Surfing The World Wide Web', 'B6.6.3.1.5', 'Illustrate how to print pages. Guide learners on how to print pages', 'e.g. selected pages, only selected pages etc. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and Computer Science.', 660),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B6.6.4.1', 'Demonstrate searching for information on the Web', 'B6.6.4.1.1', 'Show how to create a favourite link', 'Guide learners to create an Internet favourite link.', 670),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B6.6.4.1', 'Demonstrate searching for information on the Web', 'B6.6.4.1.2', 'Demonstrate deleting favourite links', 'Guide learners to delete a favourite link they have created.', 680),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B6.6.4.1', 'Demonstrate searching for information on the Web', 'B6.6.4.1.3', 'Create favourite folder. Guide learners to create a favourite folder or subfolder', 'Help learners by aiding them through the necessary steps to create a favourite folder.', 690),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B6.6.4.1', 'Demonstrate searching for information on the Web', 'B6.6.4.1.4', 'Use the links toolbar and Favourite Places', 'Guide learners to use the links toolbar. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and computer science.', 700),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B6.6.5.1', 'Demonstrate the Usage of Forms', 'B6.6.5.1.1', 'Demonstrate the types and uses of form elements', 'Explore the uses of check boxes, radio buttons, textboxes etc.', 710),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B6.6.5.1', 'Demonstrate the Usage of Forms', 'B6.6.5.1.2', 'Demonstrate the filing of forms offline', 'Guide learners to open and save a page. Lead them to fill the forms offline.', 720),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B6.6.5.1', 'Demonstrate the Usage of Forms', 'B6.6.5.1.3', 'Demonstrate uploading of files', 'Lead learners to explore the upload button by adding pictures, audio, pdf etc.', 730),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B6.6.5.1', 'Demonstrate the Usage of Forms', 'B6.6.5.1.4', 'Illustrate retrieving text, pictures, sounds and programs', 'Lead learners to explore the download button by downloading pictures, audio, pdf etc.', 740),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B6.6.5.1', 'Demonstrate the Usage of Forms', 'B6.6.5.1.5', 'Discuss more about security on the form submission', 'Guide learners to Investigate and identify security issues when typing account details online (Antivirus, Credit card details, personal passwords etc.) NB: This is to give a foundation to the learner in computing and computer science which is more concerned with uses of and development of programming together with fundamental principles of problem-solving and creativity.', 750),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B6.6.6.1', 'Show how to Customize a Browser', 'B6.6.6.1.1', 'Identify reasons for customising a web browser', 'Discuss the reasons needed for customising an item (i). to gain access to quick commands or information (ii) for side by side browsing (iii) for beautifications', 760),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B6.6.6.1', 'Show how to Customize a Browser', 'B6.6.6.1.2', 'Illustrate how to set themes', 'Explore on customisation , locate the more settings , Under appearance', 770),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B6.6.6.1', 'Show how to Customize a Browser', 'B6.6.6.1.3', 'Show how to customise the toolbar. Lead learners to explore in customising a browser…', 'e.g. themes, wallpaper, tools etc.', 780),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B6.6.6.1', 'Show how to Customize a Browser', 'B6.6.6.1.4', 'Set bookmarks. Demonstrate the meaning of bookmarks - Bookmarks, makes you save shortcuts to your favourite webpages and navigate to them in seconds from anywhere', null, 790),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B6.6.6.1', 'Show how to Customize a Browser', 'B6.6.6.1.5', 'Show how to set cookies demonstrate the steps in turning on cookies in a browser. Guide learners to turn on cookies in a browser', '1. From the Tools menu, select Internet Options and enable session cookies, click the Privacy tab.; 2. From the Settings section of the tab, click Advanced. NB: Locate and click the checkbox next to Always allow session cookies.', 800),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.1', 'Show how to create and access e-mail messages', 'Guide learners to receive email', 810),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.2', 'Illustrate how to reply to and forward received messages', 'Guide learners to use forward and reply buttons in email', 820),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.3', 'Demonstrate how to delete messages', 'Guide leaners to delete email messages.', 830),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.4', 'Illustrate filing of e-mail messages', 'Guide learners to create folders in the Inbox and sorting emails into them', 840),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.5', 'Create address list. Guide learners to create an address list', null, 850),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.6', 'Demonstrate attaching files to e-mail messages', 'Guide learners to attach files to email', 860),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B6.6.7.1', 'Demonstrate the use of Electronic Mail', 'B6.6.7.1.7', 'Demonstrate some e-mail tips', 'Assist learners in writing email using techniques as NOT writing in caps. Check the extension of files before downloading and use the subject line for summary etc. NB: This is to help the learner with the fundamental skills of creativity in computing and computer science.', 870),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B6.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B6.6.8.1.1', 'Describe other hardware used in IoT Internet of Things', 'Guide learners to discuss the IoT hardware in groups.', 880),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B6.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B6.6.8.1.2', 'Give more examples of internet of things with a consumer part and an industrial/business segment. Guide learners to list at least five gadgets used for IoT (', 'e.g. Nest Smart Thermostat, Samsung SmartThings Hub, August Smart Lock, etc.)', 890),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B6.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B6.6.8.1.3', 'Mention at least five more terms and acronyms of IoT', 'Guide learners to describe IoT use. NB: This is to help the learner to fundamental knowledge of hardware such as robots and sensors).', 900),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Digital Literacy', 'B6.6.9.1', 'Demonstrate proficiency in Digital Literacy', 'B6.6.9.1.1', 'Demonstrate how to handle private and personal information', 'Guide learners on how not post detailed personal information online.', 910),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Digital Literacy', 'B6.6.9.1', 'Demonstrate proficiency in Digital Literacy', 'B6.6.9.1.2', 'Devise various techniques on how to protect oneself from online identity theft', 'Guide learners to use strong passwords or passphrases in online sites, etc.', 920),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Digital Literacy', 'B6.6.9.1', 'Demonstrate proficiency in Digital Literacy', 'B6.6.9.1.3', 'Debate a spam and solicited messages', 'Guide leaners to differentiate spam from solicited messages.', 930),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Digital Literacy', 'B6.6.9.1', 'Demonstrate proficiency in Digital Literacy', 'B6.6.9.1.4', 'Differentiate between virtual friends and real friends', 'Guide leaners to characterise virtual and real friends', 940),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Internet Etiquette', 'B6.6.10.1', 'Demonstrate the application of Internet Etiquette', 'B6.6.10.1.1', 'Explain Internet etiquette and how to deal with it', 'Guide learners to explain Internet etiquette and elaborate on some rules associated with it', 950),
('Basic 6', 'Computing', 'computing', 'Internet and Social Media', 'Internet Etiquette', 'B6.6.10.1', 'Demonstrate the application of Internet Etiquette', 'B6.6.10.1.2', 'Investigate on the responsible use of computers', 'Guide learners to investigate on the responsible use of computers. i. Information privacy ii. Copy right. Hardware, Software and information theft', 960),
('Basic 6', 'Computing', 'computing', 'Health and Safety in Using ICT Tools', 'Health and Safety in Using ICT Tools', 'B6.7.1.1', 'Demonstrate how to apply Health and Safety measures in Using ICT Tools', 'B6.7.1.1.1', 'Identify five (5) major health hazards associated with the use of ICT tools', 'Discuss Eye strain, Eye irritation and Eye fatigue. Guide learners to discuss some major health hazards associated with the use of ICT tools.', 970),
('Basic 6', 'Computing', 'computing', 'Health and Safety in Using ICT Tools', 'Health and Safety in Using ICT Tools', 'B6.7.1.1', 'Demonstrate how to apply Health and Safety measures in Using ICT Tools', 'B6.7.1.1.2', 'Demonstrate solutions for the health related problems in ICT', 'Guide learners to brainstorm to find the solutions to the health hazards associated with the use of ICT tools.', 980),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.1.1.1.1', 'Explore and study the artworks of some international visual artists and analyse how their artworks reflect the history and culture of some communities in the world', 'use OERs (e.g. library, videos, Facebook, internet) to study and share the artworks of some international visual artists (e.g. Meshack Asare, Zingaro, Leonardo, Michelangelo, Picasso, El-Anatsui, Kara Walker, Ibrahim Mahama, Rebecca Horn);; discuss the works of the international artists studied in relation to the history and cultures of some communities in the world. For example, Ibrahim Mahama uses the transformation of materials to explore among other themes the issue of migration and the socio-economic and cultural heritage of a people;; writing a brief about their choice of artist using the following guidelines: - Name - Country of origin - Training - Type of artworks - Title of some works - Preferred Media - Contribution to the development of art.', 10),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.1.1.1.2', 'Study how the artworks of the international visual artists studied reflect the history and culture of some communities in the world and generate own ideas for creating own artworks', 'select the work of any of the international artists studied;; reflect on the themes or purposes of the works;; make an analytical study of artworks to identify the materials, tools, equipment, methods and styles used in designing and making them;; use the experience gained to generate ideas for own artworks that will reflect the history and culture of some communities in the world.', 20),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.1.1.1.3', 'Study some artworks created by international visual artists that reflect the physical and social environments of some communities in the world', 'select the designs and works of any international visual artist that reflect ideas from the physical and social environments of any community in the world; A bed designed from the A building structure based The seat of the government concept of a vehicle on the concept of a canoe of Ghana developed from and sail the concept of a stool; appreciate: discuss the selected artworks in groups and share findings with the rest of the class while focusing on the type of artwork, theme/purpose, the idea from the physical and social environment that it reflects, materials and methods/approaches used, etc.;; select and compare any two of the artworks in terms type, material, method, finishing, function and suitability, etc.; A building structure based on the concept of a canoe and sail', 30),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.1.1.1.4', 'Generate own ideas for designing and creating own visual artworks based on the physical and social environments of some communities in the world', 'use OERs to study the physical and social environments of some communities in the world and select objects/ideas that interest them and what they want to do using spidergrams. Vase Ideas Tray Pendant; present and share selected ideas using the prepared spidergrams.; reflect and generate ideas from the spidergrams into ‘thumbnail’ sketches.', 40),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.1.1.1.5', 'Study the artworks of some international visual artists that reflect topical issues in some communities in the world', 'select works of international visual artists that reflect emerging topical national issues (e.g. war, racism, terrorism, corruption, rights and responsibilities of road users, counterfeiting, intellectual property etc. digital fraud or ‘sakawa’);; discuss the works in relation to the topical global issues (concepts);; appreciate: talk about the works based on the type, theme/purpose, technique, style, materials, tools, etc.', 50),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.1.1.1.6', 'Brainstorm and generate ideas for creating own visual artworks that will reflect topical issues in some communities in the world', 'use available OERs (e.g. libraries, videos, documentaries, internet, Facebook) to research current topical issues of much concern in some communities in the world;; document results of findings in the forms of notes, statements, downloads and recordings for presentations and class discussions;; reflect on feedback from class discussions and peer reviews to generate concepts for designing and making own artworks that will reflect current topical issues of much concern in the world.', 60),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B6.1.2.2.1', 'Experiment with available visual arts media and methods to create visual artworks based on own views, knowledge and understanding of the artworks of some international visual artists', 'critically examine the works of some international artists;; make similar works of the international artists studied using available materials and tools from the local environment. e.g. - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper etc. for weaving; - odds and ends for constructing and assembling; - brushes and paint for painting; - craft tools for perforating, shaping and punching; - folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling; - needle for sewing, etc.; discuss, compare and share their experiences through jury and peer review.', 70),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B6.1.2.2.2', 'Brainstorm and generate designs for creating own visual artworks that reflect the physical and social environments of some communities in the world', 'study the ideas, forms and structures that constitute the physical and social environments of some communities in the world;; make analytical study (sketches) of the ideas, forms or structures that interest them;; develop images from the ideas, forms and structures studied;; make comprehensive (comp) sketches or final designs for reproduction in artworks;; present designs for peer review;; use the ideas or feedback from the peer review to improve upon the designs for reproduction;; experiment with available materials and tools to reproduce the comp (e.g. - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper etc. for weaving', 80),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B6.1.2.2.3', 'Brainstorm and generate designs for making own visual artworks that reflect topical issues in the world', 'reflect on current topical/global issues using available learning resources such as internet, libraries, videos, pictures, etc.;; come out with design concepts that is good for making a two or three dimensional artworks to educate and sensitise the public on the advantages and disadvantages of the current topical/global issues;; develop the concepts into comprehensive designs for reproduction.; present designs for peer review;; experiment with available materials and tools to reproduce the designs (e.g. - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper etc. for weaving; - odds and ends for constructing and assembling; - brushes and paint for painting; - craft tools for perforating, shaping and punching; - folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling; - needle, for sewing, etc.; discuss, compare and share their experiences through jury and peer review.', 90),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B6.1.2.3.1', 'Create functional and decorative visual artworks based on own views, knowledge and understanding of the medium and style of some international visual artists studied', 'present and share design concepts that reflect knowledge and understanding of the history and culture of some communities in the world;; demonstrate embedded knowledge, skill and experience in the application and use of selected medium and style of an international artist: e.g.; elements and principles of art; media: materials (oil paint, clay, paper, cement, stone, yarns, fabric etc.), tools (craft tools, carving tools, brushes, modelling tools, etc.); methods and techniques: painting, modelling, casting, carving, slabbing, pinching, coiling, sewing, stitching, printing, weaving, dyeing, embossing, quilling, etc.;; make own artworks similar to the works and style of the international artists studied using available materials and tools from the local environment;; discuss, compare and share experiences through jury and peer review.', 100),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B6.1.2.3.2', 'Create own visual artworks that reflect the physical and social environments of some communities in the world', 'present and share design concepts that reflect knowledge and understanding of the physical and social environments in the world;; demonstrate embedded knowledge, skill and experience in the application and use of selected media, technique etc. to make own creative and functional artworks (e.g. - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper, cane, bamboo stakes, etc. for weaving; - odds and ends for construction and assemblage; - brushes and paint for painting; - dyes for dyeing - craft tools for perforating, shaping and punching; - folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling;; needle for sewing, etc.;; discuss, compare and share experiences through jury and peer review.', 110),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B6.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B6.1.2.3.3', 'Create own symbolic visual artworks that communicate, educate or sensitise the public on some topical issues in the world', 'present and share design concepts intended to communicate, educate or sensitise the public on the advantages and disadvantages of current topical issues of much concern in the world. For example: - Graphic arts: posters, hand bills, flyers, banners, wall-hanging, T-shirts, brochure, cartoons, etc. - Picture-Making: painting, collage, montage, mosaic, marquetry. - Textiles: woven fabric, printed fabrics, macramé, dyed fabric, appliqué, tassels, fringes, etc. - Sculpture: plaque, shield, statuette, stools, staffs, panels, reliefs, in-the round, trophies, etc. - Jewellery: pendant, badge, beads, bracelet, brooch. - Leatherworks: bags, amulet, etc. - Ceramics/Pottery: ceremonial pots. - Basketry: containers, etc.; demonstrate embedded knowledge, skill and experience in the application and use of selected media, technique etc. to make own creative and functional artworks (e.g. - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper, cane, bamboo stakes etc. for weaving; - odds and ends for construction and assemblage; - brushes and paint for painting; - dyes for dyeing - craft tools for perforating, shaping and punching; - folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling; - needle for sewing, etc.; discuss, compare and share experiences through jury and peer review.', 120),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B6.1.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B6.1.3.4.1', 'Plan an exhibition of own functional and decorative visual artworks that reflect the medium and style of some international visual artists studied', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service);; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the exhibition;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select works for the exhibition by considering factors such as creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance);; decide on mode of display (e.g. by hanging, draping, spreading);; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition;; plan for post-exhibition activities.', 130),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B6.1.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B6.1.3.4.2', 'Plan an exhibition of own functional and decorative visual artworks that reflect the physical and social environments of some communities in the world', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service);; discuss the need for displaying portfolio of own visual artworks', 140),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B6.1.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B6.1.3.4.3', 'Plan an exhibition of own functional and decorative visual artworks that communicate, educate or sensitise the public on topical issues in the world', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service);; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the exhibition;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E- mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners)', 150),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B6.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B6.1.3.5.1', 'Exhibit own visual artworks to share creative experiences based on ideas, knowledge and understanding of the medium and style of some international artists studied', 'decide on the types and number of artworks (2-dimensional and 3-dimansional) to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that reflect the medium and style of international artists studied);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual (calligraphy writing) or ICT (computer prints): name of artist, title of work, size of work, date of production;; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully (e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors’ books). NOTE; check/monitor visitors from improper practices e.g. touching, lifting, handling and/or taking away some of the exhibits;; organise opening and closing ceremonies for the exhibition.', 160),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B6.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B6.1.3.5.2', 'Exhibit own visual artworks to share creative experiences based on ideas, knowledge and understanding of the physical and social environments of some communities in the world', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that reflect the physical and social environments of some communities in the world);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual (calligraphy writing) or ICT (computer prints): name of artist, title of work, size of work, date of production', 170),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B6.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B6.1.3.5.3', 'Exhibit own visual artworks to share creative experiences that communicate, educate or sensitise the public on topical issues in the world', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that reflect the medium and style of international artists studied);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual (calligraphy writing) or ICT (computer prints): name of artist, title of work, size of work, date of production;; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully (e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors’ books). NOTE; check/monitor visitors from improper practices (e.g. touching, lifting, handling and/or taking away some of the exhibits);; organise opening and closing ceremonies for the exhibition.', 180),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B6.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B6.1.4.6.1', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that reflect the medium and style of the international visual artists studied', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines; Description of the work: The elements in the work (e.g. dots, lines, shapes, forms, colour, texture, tone), materials used (e.g. paper, pencil, clay, wood), size of the work, number of objects/items in the work,; Subject matter: Meaning, message, topic, mood, feelings, history, religion, environment, global warming; Appraisal: What the work can be used for, likes, good things in the work, beauty, social and cultural value, correlation (connecting to other areas of learning).; Experiences to share: the design process through thinking and composing, planning and making, displaying and sharing, etc.', 190),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B6.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B6.1.4.6.2', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that reflect the physical and social environments of some communities in the world', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting', 200),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B6.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B6.1.4.6.3', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that communicate, educate and sensitise the public on topical issues in the world', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines; Description of the work: The elements in the work (e.g. dot, lines, shapes, forms, colour, texture, tone), materials used (e.g. paper, pencil, clay, wood), size of the work, number of objects/items in the work,; Subject matter: Meaning, message, topic, mood, feelings, history, religion, environment, global warming; Appraisal: What the work can be used for, likes, good things in the work, beauty, social and cultural value, correlation (connecting to other areas of learning); Experiences to share: The design process through thinking and composing, planning and making, displaying and sharing, etc.', 210),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B6.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B6.1.4.7.1', 'Analyse and appreciate own or others’ artworks and present reports as feedback on artworks that reflect the medium and style of international performing artists studied', 'display (real/photographs/video) selected works (own or that of others) that depict the medium and style of international performing artists studied;; talk about the works dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another artwork;; record/document the activity and share using an accepted social media by the class/group e.g. Facebook, Twitter, Instagram, WhatsApp, etc. .', 220),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B6.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B6.1.4.7.2', 'Analyse and appreciate own or others’ performing artworks and present reports as feedback on artworks that reflect the physical and social environments of some communities in the world', 'display (real/photographs/video) selected works (own or that of others) that reflect the physical and social environment of some communities in the world;; talk about the works dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another artwork;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp). .', 230),
('Basic 6', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B6.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B6.1.4.7.3', 'Analyse and appreciate own or others’ performing artworks and present reports as feedback on artworks that communicate, educate or sensitise public on topical issues in the world', 'display (real/photographs/video) selected works (own or that of others) that communicate, educate or sensitise the public on the advantages and disadvantages of emerging topical/global issues.; talk about the works dispassionately using agreed guidelines.; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another artwork.; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 240),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B6.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.2.1.1.1', ' reflect on the themes or purposes of the works;  make an analytical study of compositions and performances to identify the musicality, vocabulary, movement patterns, costuming, time, rhythm, speed, energy, space, etc.;  use the information gained to generate ideas for own artworks that will reflect the history and culture of some communities in the world', 'use OERs (e.g. library, videos, Facebook, internet) to study and share the artworks of some international performing artists (e.g. Michael Jackson, Fred Astaire, Elton John, Bright Okpocha (Basket Mouth), Osei Boateng, Fela Ransome Kuti, Bob Marley, Kojo Antwi, Seidou Keita, Eddie Murphy);; discuss the works of the international artists studied in relation to the history and cultures of some communities in the world. For example, ‘Exodus’ by Bob Marley;; write briefs about choice of artists using the following guidelines: - Name - Country of origin - Training - Type of artworks - Title of some works - Preferred compositions and performances - Contribution to the development of the performing arts industry.', 250),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B6.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.2.1.1.2', 'Study how the artworks of the international performing artists studied reflect the history and culture of some communities in the world and generate own ideas for creating own performing artworks Learners are) to', 'select the work of any of the international artists studied in', 260),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B6.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.2.1.1.3', 'Study how the artworks of the international performing artists studied reflect the physical and social environments of some communities in the world', 'select the compositions and performances of any international performing artist that reflect ideas from the physical and social environments of any community in the world;; appreciate: discuss the selected artworks in groups and share findings with the rest of the class focusing on the type of composition or performance, theme/purpose, the idea from the physical and social environment that it reflects, vocabulary used, rhythm, etc.;; select and compare any two of the compositions and performances in terms of type, material, method, finishing, function and suitability, etc.', 270),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B6.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.2.1.1.4', 'Generate own ideas for creating own performing artworks based on the physical and social environments of some communities in the world', 'use OERs to study the physical and social environments of some communities in the world and select objects/ideas that interest them and what they want to do using concept notes;; present and share selected ideas using the prepared concept notes;; reflect and generate ideas from the concept notes into poems, songs, dance patterns and drama.', 280),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B6.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.2.1.1.5', 'Study how the artworks of the international performing artists studied reflect topical issues in some communities in the world', 'select compositions and performance of international performing artists that reflect current topical issues of much concern in the world (e.g. war, racism, terrorism, corruption, rights and responsibilities of road users, counterfeiting, intellectual property rights, sakawa or digital fraud);; discuss the works in relation to the topical global issues (concepts);; appreciate: talk about the works based on the type, theme/purpose, technique, rhythm, style, instruments, movement patterns, costumes, etc.', 290),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B6.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B6.2.1.1.6', 'Brainstorm and generate ideas for creating own performing artworks that reflect topical issues in some communities in the world', 'use available OERs (e.g. libraries, videos, documentaries, internet, Facebook) to research current topical issues of much concern in some communities in the world;.; document results of findings in the forms of notes, statements, downloads and recordings for presentations and class discussions;; reflect on feedback from class discussions and peer reviews to generate concepts for composing music, dance, drama, poem etc. on current topical issues of much concern in the world. For example: Choice, Choice, Choice! Choice, Choice, Choice Choice, Choice, Choice We can make a choice, Take a stand, brother On the world we want, This is our time, Take a stand, sister On the way we learn When to make choices, When to make choices We can make choices; Choice, Choice, Choice Take a stand, brother Take a stand, sister When to make choices', 300),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B6.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B6.2.2.2.1', 'Experiment with available performing arts media and techniques to create performing artworks based on own views, knowledge and understanding of artworks produced by some international performing artists', 'critically examine the compositions and performances of some international artists;; make similar compositions or performances of the international artists studied using available media, techniques, elements, instruments, melodies etc. for example: - Dance by Michael Jackson - Jokes by Bright Okpocha (Basket Mouth) - Song by Bob Marley - Film by Eddie Murphy; discuss and share their experiences through peer review.', 310),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B6.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B6.2.2.2.2', 'Brainstorm and generate ideas for creating own performing artworks that reflect the physical and social environments of some communities in the world', 'study the ideas, forms and structures that constitute the physical and social environments of some communities in the world;; make analytical study of the ideas, forms, movement patterns, rhythms, sounds etc. that interest them;; develop, arrange and compose own movement patterns, lyrics, sounds, rhythms, melodies from the ideas studied in the physical and social environments.; present concepts for peer review;; use the ideas or feedback from the peer review to improve upon the arrangements for own compositions.', 320),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B6.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B6.2.2.2.3', 'Generate ideas for creating own performing artworks that reflect topical issues in the world', 'reflect on current topical issues of much concern in the world using available learning resources such as internet, libraries, videos, pictures, etc.;; come out with concepts that are good for composing music, dance, drama and poems, etc. to educate and sensitise the public on the advantages and disadvantages of current topical issues of much concern in the world;; present concepts for peer review;; discuss, compare and share their experiences through jury and peer review;; use the ideas or feedback from the peer review to improve upon the arrangements for own compositions.', 330),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B6.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B6.2.2.3.1', 'Create own performing artworks based on own views, knowledge and understanding of the techniques and styles of some international performing artists studied', 'present and share concepts that reflect knowledge and understanding of the history and culture of some communities in the world;; demonstrate embedded knowledge, skill and experience in the application and use of techniques and style of an international artist to compose own music, dance, drama, poetry, etc.;; compose and share own music, dance, drama and poems similar to the works and style of the international artists studied using available media, instruments, etc. from the local environment.; Discuss compositions through peer review.', 340),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B6.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B6.2.2.3.2', 'Create own performing artworks that reflect the physical and social environments of some communities in the world', 'present and share concepts that reflect knowledge and understanding of the physical and social environments of some communities in the world;; demonstrate embedded knowledge, skill and experience in the application and use of selected media, techniques, styles, movement patterns, rhythms, melodies etc. to compose music, dance, drama, poems etc. that reflect the physical and social environment of some communities in the world;; discuss, compare and share composition and experiences through peer review.', 350),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B6.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B6.2.2.3.3', 'Create own performing artworks that communicate, educate or sensitise the public on topical issues in the world', 'present and share their concepts intended to communicate, educate or sensitise the public on the advantages and disadvantages of current topical issues of much concern in the world;; demonstrate embedded knowledge, skill and experience in the application and use of performing arts skills, knowledge, experience, techniques, movement patterns, melodies, elements, rhythms etc. to compose own creative and expressive artworks.; discuss, compare and share composition and experiences through peer review.', 360),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B6.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B6.2.3.4.1', 'Plan a display of own performing artworks to share creative experiences of the techniques and styles of some international performing artists studied', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect emerging topical issues in Ghana;; discuss the need for performing compositions of own music, dance, drama, poetry etc.;; develop a roadmap for the performances by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the performance;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select compositions by considering e.g. creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props, etc.);; getting ready: plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance;; Plan for post-performance activities such as cleaning, appreciation, appraisal, evaluation and reporting.', 370),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B6.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B6.2.3.4.2', 'Plan a display of own performing artworks to share experiences that reflect own knowledge and understanding of the physical and social environments of some communities in the world', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect emerging topical issues in Ghana;; discuss the need for performing compositions of own music, dance, drama, poetry etc.; - develop a roadmap for the performances by; - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the performance;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select compositions by considering e.g. creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props, etc.);; getting ready: plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance.; plan for post-performance activities such as cleaning, appreciation, appraisal, evaluation and reporting. .', 380),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B6.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B6.2.3.4.3', 'Plan a display of own performing artworks to communicate, educate or sensitise the public on topical issues in the world', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect emerging topical issues in Ghana;; discuss the need for performing compositions of own music, dance, drama, poetry etc.;; develop a roadmap for the performances by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the performance;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners).; select compositions by considering e.g. creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props);; getting ready: plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance;; Plan for post-performance activities such as cleaning, appreciation, appraisal, evaluation and reporting. .', 390),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B6.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B6.2.3.5.1', 'Stage a display of own performing artworks to share creative experiences of the techniques and style of international performing artists studied', 'decide on the types and number of compositions to be performed during the event to reflect medium and style of the international artists studied based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show (e.g. explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day: opening, performances and closing. NOTE; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the performance.', 400),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B6.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B6.2.3.5.2', 'Stage a display of own performing artworks to share creative experiences of the physical and social environments of some communities in the world', 'decide on the types and number of compositions to be performed during the event to reflect the physical and social environments of some communities in the world based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show (e.g. explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day: opening, performances and closing.', 410),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B6.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B6.2.3.5.3', 'Stage a display of own performing artworks to share creative experiences that communicate, educate and sensitise the public on topical issues in the world', 'decide on the types and number of compositions to be performed during the event to communicate, educate and sensitise the public on the advantages and disadvantages of current topical issues of much concern in the world based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully (e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show for explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day: opening, performances and closing. NOTE; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the performance.', 420),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B6.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B6.2.4.6.1', 'Develop guidelines for analysing and appreciating own and others’ performing artworks that reflect the technique and style of international performing artists studied', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others’ compositions and performances on the guide guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama, poetry, etc.;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested guidelines; Music: Theme, voice production and diction, harmony and blending of parts, interpretation, the elements and knowledge of music; Dance: Theme, entrance/exit, movement variation, gestures, creativity, makeup, movement in relation to singing and drumming, costume, props, energy, stage use, stage setting and dynamics; Drama: Characterisation, makeup, gestures, voice projection, diction, use of space, aesthetics, creativity,', 430),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B6.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B6.2.4.6.2', 'Develop guidelines for appreciating and appraising own and others’ compositions and performances that reflect the physical and social environments of some communities in the world', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others compositions and performances on the guide guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama, poetry, etc.', 440),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B6.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B6.2.4.6.3', 'Develop guidelines for appreciating and appraising own and others’ performing artworks that communicate, educate or sensitise the public on topical issues in the world', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others’ compositions and performances on the guide guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama, poetry etc.;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested guidelines; Music: Theme, voice production and diction, harmony and blending of parts, interpretation, the elements and knowledge of music.; Dance: Theme, entrance/exit, movement variation, gestures, creativity, makeup, movement in relation to singing and drumming, costume, props, energy, stage use, stage setting and dynamics.; Drama: Characterisation, makeup, gestures, voice projection, diction, use of space, aesthetics, creativity.', 450),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B6.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B6.2.4.7.1', 'Analyse and appreciate own or others’ performing artworks and present reports as feedback on artworks that reflect the techniques and styles of the international performing artists studied', 'display (photographs/video) of selected performances (own or that of others) that depict techniques and styles of some international artists studied;; talk about the performances dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another composition and performance;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 460),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B6.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B6.2.4.7.2', 'Analyse and appreciate/appraise own or others’ music, dance and drama compositions and performances and present reports/feedback on works that reflect the physical and social environments of some communities in the world', 'display (photographs/video) of selected performances (own or that of others) that reflect the physical and social environments of some communities in the world;; talk about the performances dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another composition and performance;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 470),
('Basic 6', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B6.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B6.2.4.7.3', 'Analyse and appreciate own or others’ performing artworks and present reports as feedback on artworks that communicate, educate or sensitise the pubic on topical issues in the world', 'display (photographs/video) of selected performances (own or that of others) that communicate, educate or sensitise the advantages and disadvantages of current topical issues of much concern in the world;; talk about the performances dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another composition and performance;; record and document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 480),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Songs', 'B6.1.1.1', 'Read widely for pleasure, and to demonstrate independent reading and learning in the literary/content areas', 'B6.1.1.1.1', 'Relate the central messages in songs to personal experiences', 'Engage learners to sing some familiar songs from their cultural background.; Write lines of songs on chalk board and have learners read through the lines.; Demonstrate singing of the songs as learners listen attentively.; Guide learners to sing songs with stress and rhythm by clapping.; Invite learners to sing individually and in groups.', 10),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Songs', 'B6.1.1.1', 'Read widely for pleasure, and to demonstrate independent reading and learning in the literary/content areas', 'B6.1.1.1.2', 'Compose songs around values discussed', 'Have learners identify some familiar songs taught.; Guide them to sing identified songs with stress and rhythm.; Discuss the meaning of the songs and morals they teach.; Discuss values in the songs e.g. love, honesty etc.; Ensure appropriate vocabulary and expressions are used to discuss the moral values.; Put learners into small groups to compose songs around the values', 20),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Poems', 'B6.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B6.1.3.1.1', 'Relate the central messages of poems to personal experiences', 'Engage learners in reciting some familiar poems.; Introduce learners to an eight-line poem on the board.; Read/recite the poem clapping/tapping its rhythm.; Have learners read lines of the poem ensuring correct pronunciation of words.; Let learners take turns to read in groups and individually.; Have learners discuss the central message and relate it to their personal experiences.', 30),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Poems', 'B6.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B6.1.3.1.2', 'Discuss values in poems and talk about the importance of these values in society', 'Engage learners to recite some familiar poems.; Discuss the meaning of lines using appropriate expressions and vocabulary of a selected poem.; Guide learners with questions to identify some values in the lines recited.; Have them relate the values identified to day-to-day living.', 40),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Poems', 'B6.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B6.1.3.1.3', 'Compose eight-line poems', 'Engage learners to recite some familiar poems.; Discuss the process of poem composition and lead learners to write a “class” poem.; Have learners work in groups to write some meaningful lines on a given topic.; Guide learners to put the lines or sentences together to constitute a meaningful eight-line poem. Have groups recite/perform their poems to the class.', 50),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B6.1.4.1', 'Respond to stories', 'B6.1.4.1.1', 'Make connections between texts or stories and personal experiences', 'Have the learners recall one or two stories read/heard.; Tell or read a story to learners.; Invite individuals to retell the story sequentially using story map/herringbone strategy.; Lead the class to discuss the story and guide them to relate the story to their personal experiences.', 60),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B6.1.4.1', 'Respond to stories', 'B6.1.4.1.2', 'Tell stories around given themes', 'Discuss themes in story telling.; Tell a story to learners; Guide learners with questions to identify the theme of the story e.g. love, honesty, patriotism, hard work, etc.; Based on the example, have learners tell stories around given themes.; With examples encourage the use of appropriate vocabulary to depict chosen themes.', 70),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B6.1.5.1', 'Appreciate pieces of literary materials through dramatisation B6.1.5.2: Appreciate key issues in stories/sketches', 'B6.1.5.1.1', 'Dramatise/role-play whole/parts of stories/scenes, events', 'Guide learners through discussion to identify some stories/scenes, events etc.; Discuss the plot of the chosen story i.e. events at the beginning, middle, and ending.; Have learners prepare and dramatise/role-play whole/parts of stories/scene, events). Ensure the role-play/dramatisation depicts selected theme.; Ensure appropriate vocabulary use as well as correct pronunciation.', 80),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B6.1.5.2', 'Appreciate key issues in stories/sketches CONT’D', 'B6.1.5.2.1', 'Express personal opinion about moral lessons in sketches', 'Guide learners with questions to identify the structure (beginning, middle and ending) of familiar stories, e.g. Maame Akua at the Market.; Lead learners to discuss the plot of the particular story chosen.; Guide learners to role-play the story as others listen and observe and relate them to real life situations.; Using an example from the story guide learners to identify some moral values.; Learners express personal opinions about the moral lessons identified.', 90),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B6.1.5.2', 'Appreciate key issues in stories/sketches CONT’D', 'B6.1.5.2.2', 'Write plays out of a story and perform them', 'Learners read out a story from textbooks or readers.; Through discussion, guide learners to tell the plot of the story.; Show a sample, and guide learners to write a play with the story told.; Have learners produce the written play around the identified themes and values.', 100),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B6.1.5.2', 'Appreciate key issues in stories/sketches CONT’D', 'B6.1.5.2.3', 'Justify the central messages in sketches performed', 'Have learner discuss a sketch observed.; Learners say what to look for to identify key issues in a sketch.; Learners talk about lessons in the sketch.', 110),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Socials/Cultural Values and Manners', 'B6.1.6.1', 'Explore certain culturally acceptable language for communication B6.1.6.2:Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding', 'B6.1.6.1.1', 'Describe/talk about objects/personalities/ events in the country and the world', 'Revise previous discussions on the following: i. Objects – objects found in class, at home etc. ii. Dates – dates of birth. iii. Time – various times at school in the day e.g. break time. iv. Names of regions – Central, Ashanti, Northern, etc.; Lead a discussion on: i. Personalities – e.g. role models, MPs, head of institution ii. Event – festivals, games, special occasions e.g. Christmas; Guide learners to use appropriate vocabulary in the discussion.; Encourage learners to ask and answer questions for clarification of other learners'' opinions.', 120),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Socials/Cultural Values and Manners', 'B6.1.6.2', 'Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding B6.1.6.3: Use knowledge of language and communicative skills to participate in conversation', 'B6.1.6.2.1', 'View and listen attentively and for a sustained period, (', 'e.g., look at the person speaking and maintain eye contact) and record the key issues in the discussion; Introduce and explain the activity.; Demonstrate the activity/show or play it on the tape /video; Have groups/pairs converse on given topics as others observe and critique/ask questions for clarification; Encourage participants in a conversational to listen attentively and maintain eye contact.', 130),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Socials/Cultural Values and Manners', 'B6.1.6.2', 'Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding B6.1.6.3: Use knowledge of language and communicative skills to participate in conversation', 'B6.1.6.2.2', 'Listen and view for the entire duration of text/speech/presentation/video etc', 'Together with learners choose a text from their readers which has already been read.; Discuss the text e.g. title, characters, simple literary terms.; Guide learners to discuss the character traits of some characters and role-play them. Pause to ask learners questions in the process, e. g. Why do you think the characters said that?', 140),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Socials/Cultural Values and Manners', 'B6.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation CONT’D', 'B6.1.6.3.1', 'Engage in collaborative conversation with unfamiliar audience Sample topics: social issues, social values and manners', 'Show a video of a talk show or introduce a talk show by drawing on learners’ background knowledge of such activities on TV.; Identify an interesting topic e.g. “Children should not do WhatsApp”. Initiate a conversation using questions. Learners take turns to contribute to the conversation.; Put learners in groups and let them choose topics for conversation. Go round to ensure learners take turns, use facial expressions appropriately and maintain eye contact when in conversation.', 150),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Socials/Cultural Values and Manners', 'B6.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation CONT’D', 'B6.1.6.3.2', 'Demonstrate turn taking in conversation on different topics and follow agreed-upon rules for conversation and express thoughts coherently', 'Through discussion, guide learners to identify some current or recent events.; Choose one such event and engage in a model conversation with a learner earlier prepared.; Converse on a given topic with a learner as others watch.; Let learners, converse in pairs on different topics after the example. Encourage them to follow the rules of conversation. Guide the use of appropriate vocabulary by showing vocabulary cards and indirectly dropping hints of a correct word.', 160),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Socials/Cultural Values and Manners', 'B6.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation CONT’D', 'B6.1.6.3.3', 'Ask and answer questions about key details on topics under discussion', 'Put learners into groups to discuss topics such as "How I spend my holidays; My future career" etc.; Encourage learners to ask and answer questions for clarification about key details. Ensure appropriate vocabulary use by dropping hints and showing word cards.', 170),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.1', 'Employ Think Aloud and visualisation strategies to make meaning from level-appropriate texts', 'Have learners listen to teacher-read texts or video/audio recording on familiar topics.; Model the visualisation strategy to make meaning from texts heard.; Encourage learners to practise constructing meaning from the texts or play.', 180),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.2', 'Relate the sequence of events (', 'E.g. beginning, middle and end)stories/drama/texts; Referring to a recently read story, assist learners to identify the sequence of events in the story. e.g. The beginning, middle, and ending.; Groups choose a story read or heard and identify the plot structure and list events at the beginning, middle and at the end.', 190),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.3', 'Ask relevant questions to improve on understanding of moral lesson in text', 'Revise the sequence of events in a familiar story/drama/text with learners.; Together with learners, identify the characters/the settings and moral lessons in the story/drama/text read.; Discuss the roles of characters, setting and the moral values in the text.; Ask relevant questions to improve understanding of elements in the texts.; Encourage learners to also ask question.', 200),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.4', 'Use background knowledge to understand and build new knowledge while listening to informational text', 'Present an informational text on a given topic.; Use the K and W of KWL strategy to activate learners'' background knowledge.; Have learners listen to the text.; In groups, they identify and discuss the main ideas of the text.; Have learners listen to the text a second time.; In groups, learners share what they have learnt in the text.', 210),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.5', 'Express own opinions about the details of texts', 'In pairs/groups, learners share the knowledge acquired from details of a story/drama/text heard.; Put learners into groups to express personal opinions about details of texts.', 220),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.6', 'Identify the problems and solutions in texts', 'Ask questions for learners to recall the events and values in stories read.; Guide them to analyse these into cause(s) effect(s) and solution(s).', 230),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B6.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B6.1.7.1.7', 'Make simple generalisations based on the main ideas and key details of a text', 'Have learners listen to a story and identify the main ideas and key details.; Use questions to guide learners to make generalizations based on the main ideas and key details.', 240),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B6.1.8.1', 'Demonstrate understanding in asking and answering questions correctly', 'B6.1.8.1.1', 'Answer “Yes” or “No” questions correctly using the expressions that show the future', 'Through discussion, let learners identify an activity they will perform at a future time, e.g. tomorrow, next month etc.; Ask questions to elicit “Yes” or “No” answers e.g. Will you come to school tomorrow? Yes/No; Yes, I will/No, I won’t.; Introduce drills e.g. Questions and Answers Drill, for learners to practise asking and answering “Yes” or “No” Questions.', 250),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B6.1.8.2', 'Identify and use question tags correctly in speech', 'B6.1.8.2.1', 'Use positive tags, negative tags and auxiliaries in speech', 'Put learners in pairs to ask and answer simple questions in turns.; Discuss positive tags (e.g. It is cold, isn’t it?) and negative tags e.g. It isn’t cold, is it?; Demonstrate with learners the usage of positive tags, negative tags and auxiliaries in speech.; Pair learners to take turns to practise positive tags, negative tags and auxiliaries in speech.', 260),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Giving and Following Commands/ Instructions/Directions and Making and Responding to Requests', 'B6.1.9.1', 'Explore the use of verbs in commands, instructions, requests and directions appropriately in speech', 'B6.1.9.1.1', 'Create and present simple instructions or a manual on how to play a game', 'Give sample instructions on how to play a game.; Put learners into convenient groups to study and discuss the instructions.; Have each group choose a game and create instructions on how to play it.; Have learners present their work to the class for feedback.; Learners role-play.', 270),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Giving and Following Commands/ Instructions/Directions and Making and Responding to Requests', 'B6.1.9.1', 'Explore the use of verbs in commands, instructions, requests and directions appropriately in speech', 'B6.1.9.1.2', 'Make and respond to polite requests for help from unfamiliar people', 'Discuss requests e.g. as an act of asking politely or formally for something.; Demonstrate making polite requests with two or three learners.; Let learners role-play making and responding to polite requests.; Guide learners with given situations to role-play making and responding to polite requests for help from unfamiliar people.', 280),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.1', 'Demonstrate knowledge of spoken grammar and register', 'B6.1.10.1.1', 'Demonstrate awareness of the features of spoken language', 'e.g. the use of modal expressions to convey tentativeness e.g. probably, not too sure etc.; Revise important features of spoken language such as contractions and ellipsis (contractions, ellipsis e.g. A: What’s your name? B: Esi.; Let learners identify these features in their readers, story books, etc.; Let them engage in pairs and group dialogue on given topics.', 290),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.1', 'Demonstrate knowledge of spoken grammar and register', 'B6.1.10.1.2', 'Demonstrate awareness of the differences between spoken and written forms of language (simplicity/complexity of sentence structures, formal/informal)', 'Lead learners to discover differences between spoken and written forms of language. E.g. Formal and informal language: "I can''t " vs "I cannot".; Create situations for learners to practise both formal and informal forms.', 300),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.1', 'Demonstrate knowledge of spoken grammar and register', 'B6.1.10.1.3', 'Demonstrate awareness of how meaning is conveyed through appropriate pace, stress, tone', '– through news reporting; Revise how meaning is conveyed through appropriate pace, stress and tone.; Model presenting news or have learners watch a news presentation.; Put learners into groups to discuss pace, stress and tone of news presented. Guide learners to prepare and present news on given topics.', 310),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.2', 'Demonstrate the ability to communicate with accurate pronunciation and appropriate intonation B6.1.10.3: Plan and present information and ideas for a variety of purposes', 'B6.1.10.2.1', 'Speak at a good pace and with expression', 'Demonstrate a model speech: Choose a familiar topic and make a short but moving speech on it.; Have learners discuss the speech focusing on its pace and expressiveness.; Let learners speak on very short and simple topics using appropriate voice quality.; The class comment on the relevant features.', 320),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.2', 'Demonstrate the ability to communicate with accurate pronunciation and appropriate intonation B6.1.10.3: Plan and present information and ideas for a variety of purposes', 'B6.1.10.2.2', 'Read aloud clearly, at a good pace and with expression', 'Give a model reading by reading a short texts aloud.; Have pupils read aloud in pairs and in small groups.; Let them write and read out short speeches on given topics in groups. Groups may read out their speeches to the class.', 330),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.1', 'Research and deliver speeches on given informational topics', 'Have learners select topics of interest from informational texts read.; Help learners to identify the purpose and audience of sample speeches.; Have learners visit the library to research and plan their speeches.', 340),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.2', 'Draw on prior knowledge to identify subject matter and organisational structure of speech', 'Help learners to draw on their prior knowledge about speech making. For instance, ensure that learners know the roles of participants, facilitators, advisors and time-keepers in the group.; Learners must be conversant with subject matter and the (organisational) structure of their speech.; Guide learners to choose their own topics for a speech.', 350),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.3', 'Gather and select facts and ideas from one or multiple print and/ or non-print sources, appropriate to the purpose, audience, context and culture', 'Through discussion, let learners generate ideas and details appropriate to the purpose, audience, context and culture on given topics.; Provide model speeches (e.g. downloaded from the internet) for discussion. These will help learners to generate ideas for their speeches.; Guide the learners to download important speeches from the internet. Discuss the organisational structure of the speeches with them.', 360),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.4', 'Support ideas and points of view with concrete examples to convey meaning appropriate to purpose and context. Provide sample speech topics', 'Through discussion, guide learners to select facts and ideas from one or more sources such as print sources and non- print sources appropriate to the purpose, audience context and culture.', 370),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.5', 'Identify and use the appropriate register for formal and informal contexts', 'Present sample speeches to groups to study.; Provide topics and guide learners to identify related key vocabulary.', 380),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.6', 'Elaborate on points using experiences and feelings', 'Provide topics and lead class discussions to: − generate ideas; − expand the points with such details such as facts, examples, explanations and personal experiences.; Learners repeat the activity in pairs and in groups.', 390),
('Basic 6', 'English Language', 'english', 'Oral Language', 'Presentation', 'B6.1.10.3', 'Plan and present information and ideas for a variety of purposes CONT’D', 'B6.1.10.3.7', 'Speak with confidence before different audiences using appropriate verbal and non-verbal cues to convey meaning', 'Through discussion, explain the need to be able to speak with confidence before an audience.; Show video clips of well-known persons delivering speeches for learners to observe and comment on. Let learners practise these in pairs and groups.', 400),
('Basic 6', 'English Language', 'english', 'Reading', 'Phonics', 'B6.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B6.2.2.1.1', 'Read words with ending sounds like "sure" as in measure; "ture" as in creature and "tch" as in Stretch', 'Use word games to introduce words with ending sounds like "sure" as in measure; "ture" as in creature and "tch" as in Stretch.; Guide learners to play the Pick and Read game to practise reading the target words.; Have groups write sentences with the target words and read out the sentences to the class.', 410),
('Basic 6', 'English Language', 'english', 'Reading', 'Phonics', 'B6.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B6.2.2.1.2', 'Read ccvcc, cccvc words and multisyllabic words when reading continuous texts', 'Provide texts having multisyllabic words for regular practise by learners.; Model the production of the ccvcc and the cccvc words.; Ask learners to repeat the ccvcc and the cccvc words after you while you check in correct discrepancies in the pronunciation of the words. e.g. : ccvcc words - trust, striped etc. cccvc words - scrap, sprite etc. Multisyllabic words - communication, immediate etc.', 420),
('Basic 6', 'English Language', 'english', 'Reading', 'Word Families, minimal pairs and Common Digraphs', 'B6.2.3.1', 'Identify minimal pairs and common digraphs B6.2.3.1: Identify rhyming/endings words and common digraphs', 'B6.2.3.1.1', 'Use common minimal pairs to decode words', 'Give examples of minimal pairs; Using “think-pair-share”, let learners come up with more examples of minimal pairs. E.g. Two sounds One sound difference difference goat, coat, boat, road, loan wall, ball train, chain Bridge, fridge; Introduce and revise these and other similar spelling patterns using examples (two or three patterns at a time).; Drill the pronunciation of the sounds.; Have learners read several words having the spelling pattern.; Let learners also read the words in context.', 430),
('Basic 6', 'English Language', 'english', 'Reading', 'Word Families, minimal pairs and Common Digraphs', 'B6.2.3.1', 'Identify minimal pairs and common digraphs B6.2.3.1: Identify rhyming/endings words and common digraphs', 'B6.2.3.1.2', 'Use words with digraphs to make meaningful sentences', 'Have learners identify words having specific digraphs and form meaningful sentences with the words. e.gs. of digraphs: ch-chair c k - d u c k ph- phone ng- sting sh- ship q u - q u e e n wh-whale', 440),
('Basic 6', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B6.2.5.1', 'Identify and use consonant blends and clusters in reading', 'B6.2.5.1.1', 'Orally produce three-syllable words by blending sounds (phonemes), including consonant blends', 'Revise consonant blends and clusters using several spelling patterns e.g. bl, br, cl, cr, gl, gr, spr, scr, str, chr.; Drill the pronunciation of the consonant blends and clusters in isolation and in words.; Learners work in groups to identify and list words having the blends and clusters.; Have learners read the words in isolation and in context.', 450),
('Basic 6', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B6.2.5.1', 'Identify and use consonant blends and clusters in reading', 'B6.2.5.1.2', 'Use the spelling-sound correspondences for common consonant digraphs', 'In a discussion, talk about digraphs as a whole class, group and in pairs.; Have learners try to establish some rules in forming and spelling words having digraphs. E.g. ch as in church sh as in shirt gh as in tough', 460),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.1', 'Understand word meanings and usages B6.2.6.2:Build vocabulary', 'B6.2.6.1.1', 'Use level-appropriate content words (nouns, verbs, adjectives and adverbs) and function words (prepositions) appropriately in spoken and written communication', 'Using examples, explain simply the two groups of words.; Elicit sentences and have learners identify the two categories of words from their sentences.; Have sentences on sentence strips on the board or cardboards and have learners identify the function words and content words.; Have learners make meaningful sentences on their own and share with peers or in groups.', 470),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.1', 'Understand word meanings and usages B6.2.6.2:Build vocabulary', 'B6.2.6.1.2', 'Use the following terms: compound words, idiom, simile, synonym, antonym, pre-fix, suffix, phrasal verb etc. in spoken and written expressions', 'Introduce the terms one at a time using several examples.; Let learners identify the terms in the texts and stories they read.; Have learners use idioms, similes, compound words, synonyms, antonyms etc. in meaningful sentences.', 480),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.2', 'Understand word meanings and usages B6.2.6.2:Build vocabulary', 'B6.2.6.2.1', 'Develop a rich vocabulary stock through extensive reading of age-appropriate text; substituting selected nouns verbs and adjectives in a text with synonyms /near synonyms', 'Have learners regularly play several vocabulary games such as “Word hunt”, “Lucky Dip”, “I know it”, etc. Let them build a portfolio on vocabulary and use them in meaningful sentences.', 490),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.3', 'Demonstrate a rich vocabulary that supports the development of listening, reading, speaking, writing and presentation skills', 'B6.2.6.3.1', 'Deduce meaning of words from how they relate to one another', 'e.g. Hyponyms – fruits – apple Meronyms – hand – finger Meaning from context; Explain and demonstrate that the meaning of a word can be deduced from other words in its environment. E.g. Philip is glad. He is really happy. Aku is tall but her brother is short.; Put learners in groups. Let them read a text and l give the contextual meaning of selected words from the text.; Engage learners in activities such as: − Matching words with their meanings/synonyms/antonyms. − Reading a text and finding replacements for certain words in the text.; Using other strategies such as the synonym or antonym tree or synonym or antonym ‘bingo’, have learners build a portfolio of antonyms and synonyms. Meaning from word relationships hyponyms: fruit – apple meronyms: hand – finger; Have learners use the vocabulary tree and mother to child to build words using hyponyms and meronyms.', 500),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B6.2.6.4.1', 'Recognise how words are formed through compounding Have learners refresh their knowledge on affixes', '– prefixes and suffixes – , acronyms and blending using examples.; Learners choose words with given affixes and use them appropriately in sentences.; Introduce compound words in context and have learners identify their components. E.g. breakfast = break, fast; classroom = class, room.; Put learners into groups to build more compound words.', 510),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B6.2.6.4.2', 'Recognise the playful use of words in spoken and written language (jokes, riddles, puns)', 'Introduce these one at a time.; Provide and discuss examples.; Learners play games with the activity in pairs/groups.', 520),
('Basic 6', 'English Language', 'english', 'Reading', 'Vocabulary', 'B6.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B6.2.6.4.3', 'Use words suitable for purpose, audience, context and culture in relation to: type of texts (exposition/explanation, persuasive language, argumentative), medium (spoken/written), register (formal/informal) etc', 'Choose appropriate texts to guide learners identify the key elements in writing. E.g. purpose, audience, setting, characters, etc. Have them role play a simple story to bring out the importance of these elements and their usage.', 530),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.1', 'Process and comprehend level appropriate texts', 'B6.2.7.1.1', 'Construct meaning from texts', 'Select level-appropriate texts for learners.; Based on background knowledge and other factors, have learners predict what a text will be about and actively adjust comprehension while reading/viewing or listening.; Learners connect their background knowledge to help them make meaning of the text as they read.; Assist learners with a variety of questions to make meaning during and after reading the text.; Lay emphasis on the need to use the environment of a word to get its meaning.', 540),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.1', 'Process and comprehend level appropriate texts', 'B6.2.7.1.2', 'Note and recall main ideas in sequence', 'Guide learners to present facts and ideas in a sequential order. You could also adopt other strategies like the SQ3R. SQ3R strategy Have learners: S – Survey the text – (learners skim by going through the chapter, note heading/sub-heading and other features. Q – Question – generate questions about the content of the text. 3R Read – read for more information. Recite – retrieve information from text. Review – go over the main ideas in the text to consolidate understanding', 550),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.1', 'Process and comprehend level appropriate texts', 'B6.2.7.1.3', 'Scan/skim for details', 'Use texts to guide learners to grasp the main ideas as they skim/scan in 3-4 minutes and have them present their points for class discussion. Note: This must be a regular feature of reading and comprehension lessons.', 560),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.1', 'Process and comprehend level appropriate texts', 'B6.2.7.1.4', 'Read level-appropriate texts silently and closely for comprehension Give frequent and regular practice in silent and close reading using the Directed Reading Activity (DRA) strategy', null, 570),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation CONT’D B6.2.7.3: Demonstrate understanding of the use of words and phrases as used in the text B6.2.8.1: construct meaning from text read', 'B6.2.7.2.1', 'Respond to a text with reason, simple judgment and personal interpretations', 'Have learners read a short text.; Learners create a mental image from the text read. (This visualisation will help bring life to the text for learners to interpret and give their opinion and personal interpretation to the write up).; Lead a discussion of each text read with questions. Questions should elicit : − Factual information − Implied meaning − Judgment − Evaluation − Personal Response', 580),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation CONT’D B6.2.7.3: Demonstrate understanding of the use of words and phrases as used in the text B6.2.8.1: construct meaning from text read', 'B6.2.7.2.2', 'Compare and contrast two or more events in a text', 'Put learners into groups to identify, compare and contrast two or more events within a text or in different texts read or heard.; They may also compare and contrast other elements like characters and setting.', 590),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation CONT’D B6.2.7.3: Demonstrate understanding of the use of words and phrases as used in the text B6.2.8.1: construct meaning from text read', 'B6.2.7.2.3', 'Demonstrate awareness of the structure of texts (', 'e.g. introduction, body, conclusion); Guide learners systematically using given narrative texts to identify the introduction body and conclusion in it.; Have learners summarise each of these parts and make a summary of the whole text using their part summaries.', 600),
('Basic 6', 'English Language', 'english', 'Reading', 'Comprehension', 'B6.2.7.3', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation CONT’D B6.2.7.3: Demonstrate understanding of the use of words and phrases as used in the text B6.2.8.1: construct meaning from text read', 'B6.2.7.3.1', 'Determine the contextual meaning of words and phrases', 'Select a text for reading. Identify words and phrases and systematically, guide learners to work out their meanings in context.; Put learners into groups and give each group a set of words and phrases to find their meanings. Each group presents its work.', 610),
('Basic 6', 'English Language', 'english', 'Reading', 'Silent Reading', 'B6.2.8.1', 'construct meaning from text read CONT’D', 'B6.2.8.1.1', 'Read silently and reasonably for meaning from a level-appropriate text', 'Have learners stop and think about the text and know what to do when meaning is not clear. By setting a target in the text for them.; Have them read silently and at a reasonable pace to get the meaning from the text.; Direct learners’ reading with “While Reading” questions.', 620),
('Basic 6', 'English Language', 'english', 'Reading', 'Silent Reading', 'B6.2.8.1', 'construct meaning from text read CONT’D', 'B6.2.8.1.2', 'Find meaning of words as used in context', 'Have learners play vocabulary games that involve meaning and usage of words. E.g. Lucky Dip, Fishing.', 630),
('Basic 6', 'English Language', 'english', 'Reading', 'Silent Reading', 'B6.2.8.1', 'construct meaning from text read CONT’D', 'B6.2.8.1.3', 'Ask and answer questions based on a passage read', 'Prepare learners adequately before reading activities. E.g. Discussion of background knowledge, title and accompanying pictures of the reading text, prediction.; Provide “While-reading” questions.; Have learners read the text silently. Assign learners to answer a variety of questions based on the text e.g. factual, inferential and applicative questions.', 640),
('Basic 6', 'English Language', 'english', 'Reading', 'Fluency', 'B6.2.9.1', 'Read fluently to enhance comprehension', 'B6.2.9.1.1', 'Read grade-level text with meaning Use the three-stage approach (Before Reading, While Reading, and After Reading) for learners to prepare adequately and read texts and provide adequate follow-up activities', 'Use who, what, where, when, why and how of an event organiser to guide learners to adequately discuss the text and respond to questions on it.', 650),
('Basic 6', 'English Language', 'english', 'Reading', 'Fluency', 'B6.2.9.1', 'Read fluently to enhance comprehension', 'B6.2.9.1.2', 'read aloud with expressions that reflect the author’s purpose and meaning', 'Have learners read texts independently paying attention to punctuation marks, words, sentences and paragraphs. Learners use self-correction, word recognition and re-reading strategies to confirm comprehension.', 660),
('Basic 6', 'English Language', 'english', 'Reading', 'Summarizing', 'B6.2.10.1', 'Read and summarize passages read', 'B6.2.10.1.1', 'Summarise level-appropriate passages/text orally', 'Learners identify the most important ideas and restate them in their own words.; Begin from sentences and short paragraphs. E.g. Sentence: This is the boy who killed the snake. Summary: The boy killed the snake.; Lead learners with questions to do this. E.g. What did you learn from this text?', 670),
('Basic 6', 'English Language', 'english', 'Reading', 'Summarizing', 'B6.2.10.1', 'Read and summarize passages read', 'B6.2.10.1.2', 'Write short summary of a level appropriate passage/text read', 'Have learners read the passage.; Discuss it briefly with learners.; Working in groups, learners write a summary of the passage taking note of the main idea(s).; Let learners present their write up for discussion. E.g. Select main ideas from the passage without examples/illustrations/words in parenthesis.; Learners use the sequence order to write down the events that took place in the correct order.', 680),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B6.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B6.3.1.1.1', 'Identify and use nouns or noun phrases to describe conditions', null, 690),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B6.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B6.3.1.1.2', 'Identify and use: − Proper nouns to refer to organisations/events; − Count/non-count − Singular − Plural (regular, irregular) − Without plural marker', 'Revise all the types of nouns (refer to B1- B5).; Provide learners with opportunities to further practise using these nouns. E.g. a. Learners take their reading books and identify and make a list of these nouns, use them in sentences and present their work to the class for feedback. b. Use a language drill to help learners do practice activities. E.g. Pair Drill for singular/plural nouns − Learner “A” gives a noun – mango − Learner “B” gives its plural form “mangoes” and uses it in a sentence – I love mangoes.', 700),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B6.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B6.3.1.1.3', 'Use "- ing" nouns and noun phrases to refer to activities', 'E.g. I enjoy singing. I like swimming.', 710),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B6.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B6.3.1.1.4', 'Identify and use abstract nouns to refer to concepts and ideas', 'Revise abstract nouns with learners; Have learners identify abstract nouns in texts and these nouns in sentences e.g. intelligence, knowledge, idea, patience i. I admire Ama because of her patience. He appears to have a good knowledge.', 720),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B6.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B6.3.2.1.1', 'Identify and use definite and indefinite articles', 'Briefly revise nouns. Learners read/listen to a passage having several nouns.; Have them identify the nouns stating their types.; Learners identify the nouns noting words that precede them e. g. the, an; Select sentences containing nouns and articles and use them to explain the use of the articles “a”, “an” and “the” simply.; In groups, learners write sentences and underline the articles.', 730),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B6.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B6.3.2.1.2', 'Identify and use quantifiers. − ordinal first, second etc. − Some, few/little etc. − No/both, all each/every − Another, other − Fewer, less, etc', 'Revise nouns and articles briefly.; Introduce quantifiers in context. Learners listen to or read a text having several quantifiers.; Learners identify the nouns and the words that go with them (quantifiers).; Elicit examples from learners.; In pairs, one says a sentence containing a qualifier/quantifier and the other identifies the quantifiers. Role(s) are reversed.', 740),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B6.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B6.3.2.1.3', 'Identify and use possessive pronouns to show possession', 'Revise personal pronouns by having learners identify them in sentences and use them in sentences of their own.; Introduce possessive pronouns in context. E.g. i. I gave my book to Mary. ii. She sold her phone.; Learners listen to or read a passage containing several possessives (my, your, his, hers, its).; Ask them to identify words that show or indicate possession.; List words on the board and elicit others.; Have learners play a game e.g. the “Fishing Game” with cards bearing possessive pronouns. They read the word on the card and use it in a sentence.', 750),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B6.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B6.3.2.1.4', 'Identify and use demonstratives: this/that, these/those', '– concepts and ideas.; Briefly revise nouns and articles by having learners identify them in sentences.; Provide a text having the demonstratives with emphasis on the demonstratives (this, that, these, those). Read it out.; List the demonstratives and have learners read out and observe the use of the demonstratives in the sentences. Working in small groups, each group writes a number of sentences with each of the demonstratives introduced.', 760),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Pronouns', 'B6.3.3.1', 'Apply knowledge of different types of pronouns in communication', 'B6.3.3.1.1', 'Identify and use: − Reflexive pronouns to emphasis that an objects of a verb is the same person as the subject', 'e.g. myself, yourself etc. − Relative pronouns to link ideas or add information to a noun or a noun phrase e.g. which, where, whose etc. − Reciprocal pronouns e.g. each other, one another; Use a text to revise the different pronouns learnt in B1-B5.; Introduce reflexive pronouns with examples in sentences.; Discuss the reflexive pronouns with learners.; Provide a passage and group learners to identify reflexive pronouns, and use the pronouns identified in sentences.; Repeat the procedure to teach relative and reciprocal pronouns.', 770),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adjectives', 'B6.3.4.1', 'Apply the knowledge of adjectives in communication', 'B6.3.4.1.1', 'Use comparatives forms of regular and irregular adjectives to make comparisons', 'e.g. regular: fastest irregular: better; Revise the comparatives with learners.; Use practical activities to guide learners to change the positive forms of regular adjectives into comparative forms by adding -er. E.g. Compare the heights of two learners: i. Musah is tall. Safianu is short. ii. Musah is taller than Safianu.; Guide learners to form the superlative forms of regular adjectives by adding -est. E.g. Ali is the tallest.; Provide a text containing irregular forms of adjectives. Start with those that have different spelling for comparative and superlative. e.g. good better best; Provide a text for learners to identify the examples. Learners use the irregular forms of adjectives in sentences; Assist learners to use the adjectival forms position, more – and most – much more most intelligent more intelligent most intelligent; For each type or form, guide learners with examples to compare classroom objects and things within the vicinity of the school and beyond.', 780),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B6.3.5.1', 'Apply the knowledge of verbs in communication', 'B6.3.5.1.1', 'Use different types of verbs − Main verb and Helping verb (primary auxiliary and modal auxiliary)', 'Revise verbs generally. Have learners identify verbs in sentences and use them in their own sentences. − Helping verb (primary auxiliary and modal auxiliary E.g. can might, would, ought, is, are, is, are, was, were).; Choose a text (story) and have the learners work in groups to identify the main verbs. Let each group select five of the verbs and use them in sentences.; Introduce auxiliaries (primary and modal) in context one at a time. Learners listen to/read a text having several of them.; Guide learners with examples to identify and distinguish them from the main verbs and use them in sentences.', 790),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B6.3.5.1', 'Apply the knowledge of verbs in communication', 'B6.3.5.1.2', 'Use appropriate subject-verb agreement (indefinite pronouns, Singular/plural and Collective nouns', 'Revise subject-verb agreement concept learners have learnt in B4 and B5 by writing examples of sentences on the board and discussing them with learners.; Have groups of learners discuss and exemplify the following: − A singular subject goes with a singular verb. − A plural subject goes with a plural verb. − A collective subject goes with singular or plural verb.; Present a text. Put the class into groups to identify sentences showing subject –verb agreement involving Indefinite pronouns as subjects. Each group presents its work.; Conduct suitable drills for learners to have practice. Learners sit in groups to converse on a topic. E.g. “What the people in my family do daily”.', 800),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B6.3.5.1', 'Apply the knowledge of verbs in communication', 'B6.3.5.1.3', 'Use different forms of verbs: − Irregular − Infinitive to talk about personal activities', 'E.g.: I asked my friend to read the story.', 810),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B6.3.5.1', 'Apply the knowledge of verbs in communication', 'B6.3.5.1.4', 'Use the simple present form of verbs in sentences: − For scheduled future actions. − for future possibilities or plans', 'Revise the simple present in context.; Present an on-going situation to learners for them to report on it. E.g. A football game/match.; Present similar situations for learners to describe using the simple present, in groups.; Groups may write and present their work to the class.; Use texts/sentences to introduce the use of the simple present for: − scheduled future actions E.g. The bus leaves early tomorrow. − future possibilities or plans e.g. If he doesn''t come early, we shall go without him.', 820),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B6.3.5.1', 'Apply the knowledge of verbs in communication', 'B6.3.5.1.6', 'Use the past continuous form of verbs to talk about actions/events which were going on when a second one took place', 'e.g. We were playing football when the fire broke out.', 830),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B6.3.5.1', 'Apply the knowledge of verbs in communication', 'B6.3.5.1.7', 'Use the imperative form of verb to give warning and express prohibitions', 'E.g. Break the glass, and you will pay for it.', 840),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adverbs', 'B6.3.6.1', 'Apply the knowledge of different types of adverbs in communication', 'B6.3.6.1.1', 'Use adverbs to express degree and reason', 'Revise adverbs of time and manner in context: Have learners listen to/ read several sentences containing adverbs of time and manner.; Use drills and games to provide practice in using adverbs of time. E.g. Game: Lucky Dip Drill: Substitution Table Drill; Learners sit in groups to discuss issues involving use of adverbs of time.; Repeat the procedure to introduce adverbs of degree and reason. e.g. Degree: The shirt is too small for me. You are making so much noise. Reason: I sing because I like singing.', 850),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Idiomatic Expressions', 'B6.3.7.1', 'Understand and use idiomatic expressions appropriately in speech and in writing', 'B6.3.7.1.1', 'identify, explain and use idiomatic expressions correctly', 'Revise idiomatic expressions in context to guide learners identify their meanings. E.g. i. Take after (to resemble). ii. To pull down(to destroy the reputation of someone).; Together with learners, identify and write some familiar/common idiomatic expressions from learners’ culture. Then introduce other idiomatic expressions from the native language. E.g. i. Take after (to resemble). ii. To pull down(to destroy the reputation of someone).; With examples from the dictionary, help learners write idioms and their explanations.; Provide a few idiomatic expressions and let learners interpret them.; Have groups of learners write idioms and their meanings on manila cards to hang in the classroom for a while.', 860),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Conjunctions', 'B6.3.8.1', 'Apply the knowledge of conjunctions in speech and in writing', 'B6.3.8.1.1', 'Identify and use simple conjunctions - so that, when, while, if etc. to: − show purpose − express time − condition, etc', 'Revise the coordinating conjunctions – and, or, nor, but and subordinating conjunctions by having learners use them sentences.; Provide sentences for learners to join them with coordinating and subordinating conjunctions.; Provide passages and let learners identify conjunctions.; Let them do other activities like filling blanks with suitable conjunctions and using conjunction in their own sentences.; Introduce the conjunctions "so that, when, while, if etc" in context. e.g. Take a hot bath so that you can sleep well. I drank the soup while my mother was in the kitchen.; Provide opportunities for learners to use the conjunctions learnt.', 870),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Modals', 'B6.3.9.1', 'Apply the knowledge of modals in speech and in writing CONT’D', 'B6.3.9.1.1', 'Use modals to express a variety of meanings', 'Revise modal auxiliaries. − Can: conveys ability − May: asks for permission, expresses politeness, possibility − Must: obligation or compulsion, necessity − Shall/will: prediction, intention, determination etc. − Could: tentativeness, politeness − Would: politeness etc. − Might: possibility − Should: obligation − Used to: for past activity/event − Have to/ought to/need to: for obligation; Introduce them in context one or two at a time.; With examples, assist learners to use the modals in sentences to convey specific meanings such as politeness.', 880),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Prepositions', 'B6.3.10.1', 'Apply the knowledge of prepositions in oral and written communication', 'B6.3.10.1.1', 'Use prepositions to convey a variety of meanings: − Time − Purpose − Possession − Comparison', 'e.g. taller than − Support or opposition e.g. for you, against you; Revise prepositions such as those that convey meanings of position, time, direction, possession and comparison. Write examples of sentences to illustrate this.; Have learners identify common prepositions (on, in, near, under) in sentences. Let them use these prepositions in sentences.; Introduce prepositions that show support or opposition in context. E.g. for you, against you. Let them identify these prepositions in texts they have read e.g. reading passages, stories, etc.; Learners now write their own sentences with the prepositions.', 890),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adjective Phrases', 'B6.3.11.1', 'show understanding of adjective phrases in oral and written communication', 'B6.3.11.1.1', 'Form and use adjective phrases correctly', 'e.g. this is a very beautiful flower.; Revise adjectives in context by having learners identify them in sentences and use them in their own sentences.; Introduce the adjective phrase as a grammatical structure with the adjective as head. Note: The adjective phrase can be a single adjective or more. E.g. a beautiful house, a strong African oven.; Provide sentences with adjective phrases and let learners identify the adjective phrases.; In groups, learners form adjective phrases and use the phrases in sentences.', 900),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adverb Phrases', 'B6.3.12.1', 'show understanding of adverb phrases in oral and written communication', 'B6.3.12.1.1', 'Form and use adverb phrases correctly', 'E.g. He comes to the house everyday; Revise adverbs of manner, place and time.; Introduce the adverb phrase in context and get learners to understand that an adverb phrase is a grammatical structure that modifies a verb. It is usually a single word or more than a single word.; Provide several examples in context for learners to read out.; Provide short texts for learners to identify the adverb phrases.; Let learners use the adverb phrases in sentences. E.g. He comes to the house every day.', 910),
('Basic 6', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Direct and Reported Speech', 'B6.3.13.1', 'show understanding of direct and reported speeches in oral and written communication', 'B6.3.13.1.1', 'Form and use reported speech appropriately', 'Revision: Provide situations for learners to identify and use them in both present and past tenses.; Introduce the direct speech with several examples of sentences. E.g. “We saw an eagle,” said Aba. “Esi is tired,” said Mum. “Joe has become rich,” said Atongo.; Lead learners, with examples, to change direct speech into reported speech by: i. Introducing a reporting clause E.g. a. Aba said that …………… b. Mum said that………….. c. Atongo said that………. ii. Introducing “that” and completing the sentences. E.g. a. Aba said that they had seen an eagle. iii. Removing the quotation marks. E.g. b. Mum said that Esi was tired.; Put learners in pairs. Let one produce direct speech and let the other change it into reported speech. Let them change over after some time.', 920),
('Basic 6', 'English Language', 'english', 'Writing', 'Penmanship and Handwriting', 'B6.4.2.1', 'Copy and rewrite sentences correctly', 'B6.4.2.1.1', 'Write with a legible, fluent and personal handwriting style', 'Have learners select sentences from their readers.; As learners observe, demonstrate the activity by writing the sentences in joint script on the board.; Have individual learners read out the sentences.; Let learners copy the sentences into their exercise books.; Have pupils share their work with their partners.', 930),
('Basic 6', 'English Language', 'english', 'Writing', 'Penmanship and Handwriting', 'B6.4.2.1', 'Copy and rewrite sentences correctly', 'B6.4.2.1.2', 'Write complex sentences clearly and correctly', 'Revise simple and compound sentences.; Introduce the complex sentence structure by combining pairs of simple sentences. E.g. You will come. We will go. When you come, we will go.; Elicit several such sentences from learners.; Put learners into groups to identify complex sentences from texts they have read.; Have learners copy complex sentences into their exercise books.', 940),
('Basic 6', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B6.4.6.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience, and contexts CONT’D', 'B6.4.6.1.1', 'Choose appropriate ways and modes of writing for a variety of purposes, audience, and contexts, and organise facts, ideas and/or points of view in a way appropriate to the mode of delivery, using appropriate text features', 'Work with learners to select sample texts from a variety of models of writing from learners’ readers and teacher’s resources e.g. newspapers, magazines etc. You may take learners to the library for this exercise. Examples of modes of writing. i. Process ii. Narrative iii. Descriptive iv. Persuasive v. Argumentative vi. Letter Note: Present one mode of writing at a time and at different times (in different lessons).; Put learners into small groups and assign each group a mode of writing.; Have learners study the sample text.; Guide them through appropriate questions to identify the: i. Mode of writing/types of essay ii. Purpose iii. Audience; Jumble the paragraphs and have learners re-arrange the paragraphs into a coherent piece. iv. Encourage learners to use search engines to search for the different modes of writing they have studied.', 950),
('Basic 6', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B6.4.6.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience, and contexts CONT’D', 'B6.4.6.1.2', 'use key words, phrases or clauses to introduce the main idea in the paragraph', 'Display a Model Paragraph.; Put learners into groups to read the paragraph and identify what the passage is about or the main idea.; Have them identify the sentence that contains the main idea.; Let the group identify the supporting ideas and what each sentence says about the main idea.; Ask each group choose a given topic and write five sentences about the topic.', 960),
('Basic 6', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B6.4.6.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience, and contexts CONT’D', 'B6.4.6.1.3', 'Elaborate on, explain and/or justify the main ideas of a paragraph by providing relevant details and examples', 'Display a model paragraph.; By way of revision, have learners identify the main idea and supporting ideas.; Think-Pair-Share: Have pairs of learners discuss why a main idea in a paragraph needs elaboration, explanation or examples and share their views with peers and the whole class.; Give learners a topic sentence for them to elaborate on by providing details (explanation/examples). E.g. Topic sentence: Kofi is a good child.', 970),
('Basic 6', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B6.4.6.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience, and contexts CONT’D', 'B6.4.6.1.4', 'Use cohesive devices pronoun references, repeated key terms or grammatical structures to link ideas in a paragraph', 'E.g. use connectors to link contrasting ideas. Show results and purpose.; Display a sample paragraph.; Underline the cohesive devices/transitional words.; Have learners read the paragraph and discuss with their peers what the underlined words are doing in the paragraph.; Lead them in a general discussion on what the underlined words are and their roles in the paragraph. E.g. First, second, third, finally, again, also, and, besides, further, in the first place, last, likewise, next, then, too. Provide a paragraph and leave out the cohesive devices. Have learners complete the paragraph with appropriate transitional words.', 980),
('Basic 6', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B6.4.9.1', 'Apply the skills and strategies for idea generation, selection, development, organisation and revision in writing B6.4.9.2: Develop and express ideas coherently and cohesively in writing', 'B6.4.9.1.1', 'Select a topic of choice on a national issue or from different learning areas, brainstorm ideas and organize them before writing', 'Scaffold the writing process. i. Pre-writing; Have learners select and discuss a national issue with their partners.; Have learners brainstorm to generate as many ideas as possible about the topic.; Have them organise the ideas into a writing plan using an outline, a chart or an appropriate graphic organiser. E.g. line diagram Bush fires Causes Effect(s) Solution(s)', 990),
('Basic 6', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B6.4.9.2', 'Apply the skills and strategies for idea generation, selection, development, organisation and revision in writing B6.4.9.2: Develop and express ideas coherently and cohesively in writing', 'B6.4.9.2.1', 'Develop ideas into a three-paragraph draft without considering the writing conventions, linking ideas within and across paragraphs with a wider range of cohesive devices,', 'e.g. as a result, on the other hand, however.; Put learners into groups to develop their ideas in', 1000),
('Basic 6', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B6.4.9.3', 'Apply strategies for improving drafts for publishing', 'B6.4.9.3.1', 'Review, and revise the draft to produce a coherent piece by proposing grammar and vocabulary for improvement', 'Have learners review their first draft by reading it slowly and critically several times to identify words/expressions that need to be cancelled.; Guide learners with the questions below: i. Are your ideas in order and easy to understand? ii. Are all the sentences talking about the main idea of the paragraph? iii. Are all the paragraphs talking about the topic?; Have learners read their partners’ draft and offer suggestions.; Encourage learners to make as many changes as are necessary to improve their drafts.; Have learners make a clean draft for publishing.', 1010),
('Basic 6', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B6.4.9.3', 'Apply strategies for improving drafts for publishing', 'B6.4.9.3.2', 'Edit/proofread draft, checking capitalisation, usage, punctuation and spelling − Have learners pick up their clean draft (Refer to B5 4.3.1) and check for conventions', 'E.g. errors in capitalisation, punctuation and spelling. Reflective Writing A reflective writing explores who you are now and who you were before now. It focuses on a change you have experienced and reflects on how that change makes you unique.; Take learners through the writing process. Then Now chart Then Now Reasons for change; Use questions to revise: Prewriting – strategy Make a list of how things used to be and how they are now. Tell why they changed. Continue with the rest of the process: Writing, Revising, Editing and Publishing.; Now chart; Now', 1020),
('Basic 6', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B6.4.9.3', 'Apply strategies for improving drafts for publishing', 'B6.4.9.3.3', 'Publish writing piece for other peers to read and in the school magazine', 'Revise writing as a process.; Have learners share their writing with their peers classmates and families. Encourage learners to type/copy neatly their writing and submit them for publication in the class magazine, school magazine/notice board. Other places to publish include The Junior Graphic or The Daily Graphic and other print media.', 1030),
('Basic 6', 'English Language', 'english', 'Writing', 'Creative/Free Writing', 'B6.4.11.1', 'Create texts', 'B6.4.11.1.1', 'Write freely about topics of choice on national issues and issues from different learning areas', 'Have learners select a topic of their choice on national issues and issues from different learning areas.; Guide learners to brainstorm and generate ideas.; Have learners organise their ideas to write their first draft.; They revise their first draft.; Learners then, peer edit their work.; Have them present their work for class discussion and correction.; They then write the final draft and display their work for their peers to read.', 1040),
('Basic 6', 'English Language', 'english', 'Writing', 'Creative/Free Writing', 'B6.4.11.1', 'Create texts', 'B6.4.11.1.2', 'Write poems and imaginative narrative stories using ideas from poems and imaginative texts read or viewed', 'Select a narrative text or story to revise the elements of narrative: − Title − Characters − Setting − Plot/storyline − Conflict, dialogue', 1050),
('Basic 6', 'English Language', 'english', 'Writing', 'Descriptive Writing', 'B6.4.12.1', 'Demonstrate knowledge of descriptive words/expressions in writing', 'B6.4.12.1.1', 'Use descriptive words/sound devices/ figurative language to describe events/situations/places/personal experiences and events', 'Briefly revise the writing process by having learners name the stages and say what happens at each stage.; Revise descriptive writing with learners; Have learners select a topic e.g. “A Day I will never forget”.; Provide a sample text. Guide learners to identify the descriptive words and expressions:; Discuss the descriptive words and expressions with learners.; Put learners into groups and guide them through the writing process to describe events/situations/places of their choice and personal experiences. Focus on the use of: − Descriptive (adjectives) words. − Figurative language e.g. simile – metaphor, personification, sound devices Note: Sensory details are experiences through the senses: sight, smell, touch, taste. − Sensory details (Allow a reader to visualize a person, a place, a thing or an idea).', 1060),
('Basic 6', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B6.4.13.1', 'Support an opinion in writing B6.4.13.2: Write arguments to support claims with clear reasons and relevant evidence', 'B6.4.13.1.1', 'Write explanations and examples to support opinions', 'Present a motion to learners. E. g. A lawyer is more important than a doctor.; Discuss the meaning and implication of the motion with pupils and invite them to take a stand either for or against the motion.; Put learners into two groups: for the motion and against the motion and write down what they think about it. Groups read out their opinions to the class for discussions.', 1070),
('Basic 6', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B6.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B6.4.13.2.1', 'Introduce claims and support with clear reasons in order of importance and evidence using credible sources and demonstrate understanding of the topic or text', 'Working in groups, learners provide reasons for the opinions they hold on a topic.; Guide groups to provide evidence for the opinions they hold.; Have groups present their work for discussions.', 1080),
('Basic 6', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B6.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B6.4.13.2.2', 'Use words, phrases, and clauses to clarify the relationships among claim(s) and reasons', 'Lead learners to discuss appropriate language for arguments e. g. use of adjectives in their various forms.; You may read out model argumentative essays to guide learners.', 1090),
('Basic 6', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B6.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B6.4.13.2.3', 'Establish and maintain a formal style', 'Using models, discuss the basic structure of an argumentative piece: − Introduction. − Reasons for the stand taken. − Conclusion.; Have learners in groups to present full compositions using class discussions.', 1100),
('Basic 6', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B6.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B6.4.13.2.4', 'Provide a concluding statement that follows from argument presented and pose a rhetorical question on the topic', 'Have them go through the writing process to present/state an opinion, explain and justify it so as to persuade the reader to accept the opinion or point of view.; Teach the features of a debate e.g. vocatives, taking a stand etc. Put learners in groups and have them select a controversial or debatable topic. Divide the class into two to prepare using the writing process as a guide, and to debate on the topic.', 1110),
('Basic 6', 'English Language', 'english', 'Writing', 'Expository /Informative Writing', 'B6.4.14.1', 'Write the event of the day', 'B6.4.14.1.1', 'Write short paragraphs to describe incidents', 'E.g. accidents, fire outbreak.; Briefly revise the writing process by having learners recall the stages and explain the features and relevance of each stage.; Have learners select a topic and brainstorm to generate ideas.; Put them into groups to organise the points for the development of paragraphs.; Assign learners to individually develop the points into outlines and then into a draft.; Let them do self and peer-editing before finally presenting the final work. Learners present their finished work in groups.', 1120),
('Basic 6', 'English Language', 'english', 'Writing', 'Expository /Informative Writing', 'B6.4.14.2', 'Write the event of the day', 'B6.4.14.2.1', 'Write articles on varied topics', null, 1130),
('Basic 6', 'English Language', 'english', 'Writing', 'Letter Writing', 'B6.4.15.1', 'Write informal letters on given topics', 'B6.4.15.1.1', 'Write to friends to express their views on given topics using appropriate letter formats', 'Discuss the features of informal letters with learners.; Give examples of formal letters to them and let them talk about the similarities and differences between formal and informal letters.; Brainstorm to guide learners generate topics they would want to write on and let each group choose a topic.; Learners identify purpose and audience and make a mind map to guide the writing.; Each group writes an informal letter and edits it. The letters are passed round the groups for editing.', 1140),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Capitalisation', 'B6.5.1.1', 'Use capital letters to start the first word in direct speech', 'B6.5.1.1.1', 'Follow appropriate mechanical convention', 'Ask individual learners to write a formal letter each on a given topic, paying attention to correct use of capital letters, the full stop, comma, question mark, exclamation mark, quotation marks, apostrophe, hyphen etc.', 1150),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Punctuation', 'B6.5.2.1', 'Show understanding of how punctuations are used appropriately in writing', 'B6.5.2.1.1', 'Use : − the comma around a phrase for the modifying of the proceeding noun; − quotation marks to indicate direct speech; − apostrophe to show plural possession', 'Revise punctuations with learners. − Give out samples of relevant texts to groups of learners to identify the punctuation marks used. e.g.; 1. Kofi, my friend, will help me do my homework; 2. I like football," said Ama.; 3. This is girls'' work.; 4. Mary: Kofi, do you like my pen? Kofi: Yes, I do.; Write a text on the board, leaving out the punctuation marks.; Have the whole class punctuate it.; Have them study unpunctuated texts individually for a few minutes and then re-write the texts using appropriate punctuation marks where they have been omitted.', 1160),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Naming Words/Nouns', 'B6.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B6.5.3.1.1', 'Identify and use nouns or noun phrases to describe conditions', null, 1170),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Naming Words/Nouns', 'B6.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B6.5.3.1.2', 'Identify and use: proper nouns to refer to organisations/events − Count/non-count − Singular − Plural (regular, irregular) − without plural marker − Gender', 'Revise all the types of nouns with learners (refer to B1-B5).; Provide learners with opportunities to further practice using these nouns. E.g. a. Learners take their reading books and identify and make a list of these nouns, use them in sentences and present their work to the class for feedback. b. Use language drills and games to help learners to practice. e.g. a pair drill for singular/plural nouns − Learner “A” gives a noun – mango − Learner “B” gives its plural form “mangoes” and uses it in a sentence – I love mangoes.; Provide further practice activities to build on learners'' knowledge on nouns.', 1180),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Naming Words/Nouns', 'B6.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B6.5.3.1.3', 'Use the "-ing" nouns to refer to activities', 'e.g. I enjoy singing. I like swimming.', 1190),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Naming Words/Nouns', 'B6.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B6.5.3.1.4', 'Identify and use abstract nouns to refer to concepts and ideas', 'Revise abstract nouns.; Have learners identify abstract nouns in texts and use them in sentences e.g. intelligence, knowledge, idea, patience i. I admire Ama because of her patience. ii. He appears to have a good knowledge of what we are saying.', 1200),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B6.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B6.5.4.1.1', 'Differentiate between how the simple past and the present perfect tense forms are used in speech and in writing', 'Revise the simple present and present perfect tenses by using examples and situations.; Distribute copies of a sample story and let them identify the simple past verbs, how they are used in sentences and identify modals used. Use this as a guide to let learners write a story using the simple past.; Learners in pairs write their own stories making sure they use both tense forms.; Prepare a grid containing all that could be needed to guide the pairs to do their own editing paying attention to the correct use both tense.', 1210),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B6.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B6.5.4.1.2', 'Explore the use of the simple past verb form and participle form', 'Let learners write a story. E.g. about what happened after school on Monday.; Discuss the essay topic with learners and use the webbing strategy to help them write on the chosen topic. Learners write individually.; Learners exchange their work for editing as teacher guides by focusing on the past verb form and participle form.; Assist those whose essays are only in the simple past to some in the past participle tense.; Learners rewrite their essays incorporating the corrections.; Have learners write on another topic individually using the simple past verb form as well as the past participle form.', 1220),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B6.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B6.5.4.1.3', 'Use a range of verb forms in speech and in writing', 'Guide learners, with examples, to form sentences in the past perfect tense. Learners narrate a short event using the simple past and past perfect tenses.; Guide learners with examples to construct sentences using the past perfect form of verbs. E.g. When you came I had already finished the work.', 1230),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B6.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B6.5.4.1.4', 'Apply the use of the singular and plural subject and the verb forms that go with them', 'E.g. Let children explore the varied usage of the various tenses (simple, present perfect, and past perfect); Learners write on a topic using the simple present, present perfect and past perfect tenses.; Discuss the topic with learners contributing with sentences containing the present perfect and past perfect.; Let learners write in bits e.g. First start with introduction and guide them to edit. Learners then write a whole essay on a chosen topic individually', 1240),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Qualifying Words- Adverbs', 'B6.5.6.1', 'Understand and use adverbs correctly in speech and in writing', 'B6.5.6.1.1', 'Use adverbs to express degree and reason', 'Revise adverbs of time and manner in context: Have learners listen to and read several sentences containing adverbs of time and manner.; Use drills and games to provide practice in using adverbs of time. E.g. Game: Lucky Dip Drill: Substitution Table Drill; Learners sit in groups to discuss issues involving use of adverbs of time.; Repeat the procedure to introduce adverbs of degree and reason. e.g. Degree: The shirt is too small for me. You are making so much noise. Reason: I sing because I like singing.; Have groups construct short paragraphs using such adverbs.', 1250),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Simple Prepositions', 'B6.5.7.1', 'Apply the knowledge of prepositions in oral and written communication', 'B6.5.7.1.1', 'Use prepositions to convey a variety of meanings − Time − Purpose − Possession − Comparison', 'e.g. taller than − Support or opposition for you, against you; Revise prepositions such as those that convey meanings of position, time, direction, possession and comparison. Write examples of sentences to illustrate this.; Have learners identify common prepositions (on, in, near, under) in sentences. Let them use these prepositions in sentences.; Introduce prepositions that show support or opposition in context. E.g. for you, against you. Let them identify these prepositions in texts they have read e.g. reading passages, stories, etc.; Learners now write their own sentences with the prepositions.', 1260),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Conjunctions', 'B6.5.8.1', 'Apply the knowledge of conjunctions in speech and in writing', 'B6.5.8.1.1', 'Identify and use conjunctions', '– so that, when, while, if etc. to: Show purpose Express time Express condition; Revise the use of conjunctions learners have learnt in B4, B5 and B6 Strand 3, Sub-strand 8 – and, but, or, nor, so that, when, while, if, unless etc. to express purpose, time, condition etc.; Learners write stories on topics of their choice using the conjunctions to link ideas in their sentences.; Have learners peer-edit one another’s work.', 1270),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Simple, Compound and Compound Sentences', 'B6.5.9.1', 'Apply knowledge of grammatical rules to form words, phrases and sentences CONT’D', 'B6.5.9.1.1', 'Identify subjects and verb in complex sentences', 'Revise nouns and verbs by having learners identify them and use them in sentences.; Revise simple subjects and predicates in sentences.; Elicit sentences from learners and let them identify the subjects and predicates of their own sentences.; Assign pairs of learners to supply extracts from comprehension passages and identify the subjects and predicates of the sentences.; Let learners describe an event they had participated in using complex sentences. They edit it to demonstrate their knowledge of subject and predicate.', 1280),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Simple, Compound and Compound Sentences', 'B6.5.9.1', 'Apply knowledge of grammatical rules to form words, phrases and sentences CONT’D', 'B6.5.9.1.2', 'Construct complex sentences correctly', 'Review the use of coordinators in sentences. Learners write examples of sentences containing coordinators.; Let learners join pairs of simple sentences into compound ones.; Introduce complex sentences with several examples; Elicit similar sentences from learners; Have learners change compound sentences into complex ones.; In groups learners study extract of reading passages to identify complex sentences.', 1290),
('Basic 6', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Spelling', 'B6.5.10.1', 'Spell words accurately', 'B6.5.10.1.1', 'Check pieces of literary work for spelling', 'Give learners an extract containing wrongly spelt words. Guide them to correct the spellings.; Have learners read a short story and write a continuation of the story. E.g. Cinderella wore the shoes and she was taken away to marry the prince.; Let their story begin from this end. Use a variety of local stories.; Each effort is followed by editing focused on spelling.; Learners write their stories in groups and as individuals. Guide learners to create additional groups to correct spellings of words.', 1300),
('Basic 6', 'English Language', 'english', 'Extensive Reading', 'Building the Love and Culture of Reading', 'B6.6.1.1', 'Read widely for pleasure, and to demonstrate independent reading and learning in the literary/content areas', 'B6.6.1.1.1', 'Read and critique a variety of age- and level appropriate books and present a one-page critical commentary based on a set of criteria, on each book read', 'Lead discussion on the importance of reading widely.; Have learners read books of their choice independently during the library period.; Learners think-pair-share their stories with peers.; Ask each learner to write a-two-paragraph summary of the book read.; Invite individuals to present their work to the class for feedback.; Encourage them to visit the local library to read and borrow books.; Encourage them to share whatever they read with their mates.', 1310);
